insert into public.therapist_resources (slug, title, kind, summary, goal, audience, duration, body_md, fields, tags, created_at)
values
  ('unexpected-bill-first-hour-steps-sheet', 'Unexpected Bill First Hour Steps Sheet', 'worksheet'::resource_kind, 'A sheet for the first hour after a surprise expense lands: what is known, what is owed, who to call and when to decide.', 'Use it to help a client turn the jolt of an unexpected bill into a short list of next steps instead of a spiral.', array['Adults']::text[], '20 minutes when the bill arrives', 'A car repair, a medical statement or a tax notice tends to arrive with a surge of dread that makes the number feel bigger than it is. The sheet asks the client to copy the exact amount and due date, list what they actually know versus what they are assuming, name one person or office to call, and set a time tomorrow to decide anything that does not need deciding tonight. Review it in session for the gap between the dread and the facts. Watch for a client who avoids opening the envelope at all; agree on a time to open it together if needed.', '[{"id": "f0", "type": "textarea", "label": "The exact amount, who it is from and the date it is due:"}, {"id": "f1", "type": "textarea", "label": "What I know for certain about this bill, and what I am guessing:"}, {"id": "f2", "type": "textarea", "label": "The one phone call or email that would clear up the biggest question:"}, {"id": "f3", "type": "textarea", "label": "What has to be decided tonight, and what can wait until a set time tomorrow:"}, {"id": "f4", "type": "textarea", "label": "Who I can tell about it so I am not carrying it alone:"}, {"id": "f5", "type": "textarea", "label": "How my body feels right now, and one thing I will do for the next hour that is not math:"}]'::jsonb, array['stress', 'planning', 'problem solving']::text[], '2026-11-18T15:00:00+00:00'::timestamptz),
  ('weekend-that-did-not-restore-me-review-sheet', 'Weekend That Did Not Restore Me Review Sheet', 'worksheet'::resource_kind, 'A Monday review of a weekend that left the client as tired as Friday, sorting what filled the hours from what refilled them.', 'Use it to help a client see why free time is not restoring them and change one thing about next weekend.', array['Adults']::text[], '20 minutes on Monday', 'Clients often arrive on Monday saying the weekend disappeared. The sheet asks them to reconstruct it in blocks, mark each block as draining, neutral or refilling, note how much was chosen versus landed on them, and spot the hours lost to scrolling or errands that were meant to be rest. Then they pick one change for the coming weekend, protected on the calendar. Watch for a client who rates every pleasant hour as wasted because it was not productive, and for one who had no unscheduled hour at all.', '[{"id": "f0", "type": "textarea", "label": "My weekend in blocks, Friday evening through Sunday night, as best I remember it:"}, {"id": "f1", "type": "textarea", "label": "For each block: draining, neutral or refilling:"}, {"id": "f2", "type": "textarea", "label": "Which blocks I chose, and which were chosen for me or just happened:"}, {"id": "f3", "type": "textarea", "label": "The hours that slipped away without my deciding, and where they went:"}, {"id": "f4", "type": "textarea", "label": "The one thing that actually refilled me, however small:"}, {"id": "f5", "type": "textarea", "label": "One change I will protect on next weekend''s calendar:"}]'::jsonb, array['self-care', 'planning', 'energy']::text[], '2026-11-18T15:00:00+00:00'::timestamptz),
  ('afternoon-slump-hour-map-and-plan-sheet', 'Afternoon Slump Hour Map and Plan Sheet', 'worksheet'::resource_kind, 'A map of the client''s daily energy dip, what they reach for when it hits and a plan for the hour that works better than fighting it.', 'Use it to help a client stop treating the afternoon dip as a personal failing and plan around it instead.', array['Adults', 'Teens']::text[], 'One week of logging, then 20 minutes', 'Most people have a predictable low point in the afternoon and judge themselves for it. The sheet has the client note for a week when the dip begins, how long it lasts, what they usually do during it and how they feel afterward. Then they design the slump hour: which tasks fit a low-energy brain, what movement or light is available, and what they will stop expecting of themselves in that window. Watch for a client who schedules their hardest work at their lowest point, and for one who uses the dip as evidence of laziness.', '[{"id": "f0", "type": "textarea", "label": "Each day this week: when my energy dropped, and when it came back:"}, {"id": "f1", "type": "textarea", "label": "What I usually do during the dip, and how I feel an hour later:"}, {"id": "f2", "type": "textarea", "label": "Tasks that suit a tired brain and could live in that hour:"}, {"id": "f3", "type": "textarea", "label": "Movement, light or a short break I could add at the start of the dip:"}, {"id": "f4", "type": "textarea", "label": "What I will stop expecting of myself in that window:"}, {"id": "f5", "type": "textarea", "label": "After a week: what changed about the hour, and about how I judged it:"}]'::jsonb, array['energy', 'self-monitoring', 'routines']::text[], '2026-11-18T15:00:00+00:00'::timestamptz),
  ('new-town-first-month-anchors-sheet', 'New Town First Month Anchors Sheet', 'worksheet'::resource_kind, 'A planner for the first month after a move that fixes a few anchors: a route, a place, a face and a weekly rhythm.', 'Use it to help a client who has relocated build footholds before loneliness or disorientation settles in.', array['Adults', 'Teens']::text[], '30 minutes to plan, one month to use', 'A move strips away the small automatic comforts a client never noticed: the familiar walk, the barista who nods, the standing Tuesday plan. The sheet asks them to choose a route to walk regularly, one third place to return to weekly, one person to see or call on a schedule, and one activity that happens at the same time each week. It also asks what from the old place can continue by phone or online. Review at the end of the month for which anchors held. Watch for a client who waits to feel settled before doing any of this.', '[{"id": "f0", "type": "textarea", "label": "The walk or route I will repeat often enough to know it by heart:"}, {"id": "f1", "type": "textarea", "label": "The one place outside home I will return to every week:"}, {"id": "f2", "type": "textarea", "label": "The person here, or from before, I will see or call on a set day:"}, {"id": "f3", "type": "textarea", "label": "The weekly activity that will happen at the same time no matter what:"}, {"id": "f4", "type": "textarea", "label": "What from my old life continues by phone, video or mail:"}, {"id": "f5", "type": "textarea", "label": "At the end of the month: which anchors held, and what still feels unfamiliar:"}]'::jsonb, array['transitions', 'connection', 'planning']::text[], '2026-11-18T15:00:00+00:00'::timestamptz),
  ('retirement-week-shape-planner-sheet', 'Retirement Week Shape Planner Sheet', 'worksheet'::resource_kind, 'A week planner for a newly retired client that gives each day a reason to get up, a reason to go out and a reason to see someone.', 'Use it to help a client whose days have lost their edges build a weekly shape that is theirs rather than work''s.', array['Adults']::text[], '40 minutes, reviewed monthly', 'Retirement removes the structure that used to arrive by default, and many clients describe the days running together within weeks. The sheet asks for a rough rhythm rather than a timetable: a morning anchor for each day, at least three outings a week, two planned contacts with people, one standing commitment that others count on, and open space on purpose. Watch for a client who fills every hour out of fear of emptiness, and for one who treats any structure as a return to being bossed around. Review the shape monthly rather than daily.', '[{"id": "f0", "type": "textarea", "label": "What used to give my days their shape, and what I miss and do not miss about it:"}, {"id": "f1", "type": "textarea", "label": "A morning anchor for each day of the week, however small:"}, {"id": "f2", "type": "textarea", "label": "The three or more times I will leave the house this week, and for what:"}, {"id": "f3", "type": "textarea", "label": "The two people I will see or speak with this week, planned in advance:"}, {"id": "f4", "type": "textarea", "label": "One standing commitment where someone else is counting on me:"}, {"id": "f5", "type": "textarea", "label": "The open hours I am leaving open on purpose, and what I will tell myself about them:"}]'::jsonb, array['transitions', 'routines', 'planning']::text[], '2026-11-18T15:00:00+00:00'::timestamptz),
  ('nobody-laughed-at-my-joke-thought-record', 'Nobody Laughed at My Joke Thought Record', 'cbt'::resource_kind, 'A thought record for the moment a joke lands flat, catching the leap from silence to I am embarrassing.', 'Use it to help a client separate one quiet room from the verdict their mind delivered about them.', array['Adults', 'Teens']::text[], '15 minutes after the moment', 'A joke that gets no laugh is a small, common event that some clients experience as proof of something global. The record walks through the situation, the hot thought, the emotion and its intensity, the evidence for and against, and a balanced alternative, then asks what they did next. Pay attention to the behavior column: the client who went quiet for the rest of the evening has turned one moment into a pattern. Use the alternative explanations prompt to list ordinary reasons a joke falls flat that have nothing to do with the teller.', '[{"id": "f0", "type": "textarea", "label": "What happened: where I was, who was there, what I said and what followed:"}, {"id": "f1", "type": "textarea", "label": "The thought that arrived in the silence, word for word:"}, {"id": "f2", "type": "textarea", "label": "What I felt and how strongly, from 0 to 100:"}, {"id": "f3", "type": "textarea", "label": "Evidence that the thought is true, and evidence that it is not:"}, {"id": "f4", "type": "textarea", "label": "Ordinary reasons a joke falls flat that have nothing to do with me:"}, {"id": "f5", "type": "textarea", "label": "A fairer thought, and how strong the feeling is now:"}, {"id": "f6", "type": "textarea", "label": "What I did for the rest of the evening, and what I would do differently:"}]'::jsonb, array['thought record', 'automatic thoughts', 'self-criticism']::text[], '2026-11-18T15:00:00+00:00'::timestamptz),
  ('say-i-do-not-know-out-loud-experiment-sheet', 'Say I Do Not Know Out Loud Experiment Sheet', 'cbt'::resource_kind, 'A behavioral experiment in which the client admits not knowing something in a meeting or class and records what actually follows.', 'Use it to test a client''s prediction that appearing uninformed will cost them respect.', array['Adults', 'Teens']::text[], 'One week', 'Clients who bluff, go silent or over-prepare often share a prediction: if I say I do not know, people will think less of me. The sheet has them write the prediction with a confidence rating, choose a low-stakes setting, say the words once this week, and record the actual response, their own anxiety before and after, and any reaction over the following days. Help them pick a setting where the stakes are real enough to matter but small enough to try. Watch for a client who follows the admission with a flood of apology that muddies the result.', '[{"id": "f0", "type": "textarea", "label": "Where and with whom I will say I do not know this week:"}, {"id": "f1", "type": "textarea", "label": "My prediction of what will happen, and how sure I am from 0 to 100:"}, {"id": "f2", "type": "textarea", "label": "The exact words I will use, without an apology attached:"}, {"id": "f3", "type": "textarea", "label": "What actually happened in the room, including faces and replies:"}, {"id": "f4", "type": "textarea", "label": "My anxiety before, during and ten minutes after:"}, {"id": "f5", "type": "textarea", "label": "Anything that came of it over the next few days:"}, {"id": "f6", "type": "textarea", "label": "What the result says about my prediction, and what I want to try next:"}]'::jsonb, array['behavioral experiment', 'predictions', 'perfectionism']::text[], '2026-11-18T15:00:00+00:00'::timestamptz),
  ('forgot-a-friends-birthday-thought-record', 'Forgot a Friend''s Birthday Thought Record', 'cbt'::resource_kind, 'A thought record for the sinking moment of realizing a birthday passed, catching the slide from a slip to I am a terrible friend.', 'Use it to help a client respond to a missed date with repair rather than a character verdict.', array['Adults', 'Teens']::text[], '15 minutes', 'Forgetting a birthday is a reliable trigger for labeling, and the label tends to stop the client from doing the one useful thing, which is to reach out late. The record captures the situation, the automatic thought, the feeling, the evidence either way, and a fairer thought, then adds a concrete repair step with a time attached. Look for the all-or-nothing rule underneath, often some version of a good friend never forgets. Ask what the client would think of a friend who forgot theirs and called the next day.', '[{"id": "f0", "type": "textarea", "label": "What I realized, when, and how I found out:"}, {"id": "f1", "type": "textarea", "label": "The thought that followed, in my exact words:"}, {"id": "f2", "type": "textarea", "label": "The feeling and its strength from 0 to 100:"}, {"id": "f3", "type": "textarea", "label": "What I would think of a friend who forgot mine and reached out late:"}, {"id": "f4", "type": "textarea", "label": "Evidence about what kind of friend I have actually been this year:"}, {"id": "f5", "type": "textarea", "label": "A fairer thought about the slip:"}, {"id": "f6", "type": "textarea", "label": "The message or call I will make, and when:"}]'::jsonb, array['thought record', 'self-criticism', 'thinking traps']::text[], '2026-11-18T15:00:00+00:00'::timestamptz),
  ('i-should-have-known-hindsight-check-sheet', 'I Should Have Known Hindsight Check Sheet', 'cbt'::resource_kind, 'A sheet that separates what the client knew at the time of a decision from what they only learned afterward.', 'Use it to help a client who judges past choices with present knowledge weigh them with the information they actually had.', array['Adults']::text[], '20 minutes', 'After a bad outcome the mind rewrites the past so the result looks obvious, and the client concludes they were careless or foolish. The sheet has them describe the decision, list what they knew at the time, list separately what they learned only afterward, note what a reasonable person with the first list might have chosen, and then re-rate their own responsibility. Watch for information quietly migrating from the second column into the first. Useful for regret after a job move, an investment, a medical choice or a relationship.', '[{"id": "f0", "type": "textarea", "label": "The decision I keep judging, and when I made it:"}, {"id": "f1", "type": "textarea", "label": "Everything I actually knew at the moment I decided:"}, {"id": "f2", "type": "textarea", "label": "Everything I learned only after the outcome:"}, {"id": "f3", "type": "textarea", "label": "What a reasonable person with only the first list might have chosen:"}, {"id": "f4", "type": "textarea", "label": "My responsibility for the outcome, rated before and after this sheet:"}, {"id": "f5", "type": "textarea", "label": "What I would tell someone else who made the same call with the same facts:"}]'::jsonb, array['thinking traps', 'self-blame', 'decisions']::text[], '2026-11-18T15:00:00+00:00'::timestamptz),
  ('spilled-coffee-before-the-meeting-thought-record', 'Spilled Coffee Before the Meeting Thought Record', 'cbt'::resource_kind, 'A thought record for a small mishap right before something important, catching the forecast that the whole event is now ruined.', 'Use it to help a client notice how one stain becomes a ruined day in the space of a hallway.', array['Adults', 'Teens']::text[], '10 minutes', 'The spill, the run in the tights or the dropped papers before a meeting is a tidy example of fortune telling: the client predicts the rest of the hour from the first thirty seconds. The record captures the mishap, the prediction, the emotion, what actually happened in the meeting, and how much the mishap mattered to anyone else. Keep it short so it can be done between the hallway and the room. Watch for a client who spent the meeting monitoring the stain instead of the conversation.', '[{"id": "f0", "type": "textarea", "label": "The small thing that went wrong, and how long before the event:"}, {"id": "f1", "type": "textarea", "label": "What I predicted about the rest of the event, in my exact words:"}, {"id": "f2", "type": "textarea", "label": "What I felt walking in, from 0 to 100:"}, {"id": "f3", "type": "textarea", "label": "What actually happened once it started:"}, {"id": "f4", "type": "textarea", "label": "How many people noticed or mentioned the mishap:"}, {"id": "f5", "type": "textarea", "label": "What I was paying attention to during the meeting, the stain or the room:"}, {"id": "f6", "type": "textarea", "label": "What I would say to my prediction next time it shows up early:"}]'::jsonb, array['thought record', 'predictions', 'thinking traps']::text[], '2026-11-18T15:00:00+00:00'::timestamptz),
  ('parrot-on-the-shoulder-repeating-thoughts-page', 'Parrot on the Shoulder Repeating Thoughts Page', 'act'::resource_kind, 'A defusion page that casts a repetitive thought as a parrot on the shoulder, saying the same line because that is what parrots do.', 'Use it to help a client hear a worn-out thought as a repeated squawk rather than fresh news each time it arrives.', array['Adults', 'Teens']::text[], '15 minutes, then daily practice', 'Some thoughts have said the same sentence for years, and the client still treats each repetition as information. The page has them write the parrot''s two or three lines, count how many times it said them today, notice that the words never change while the days do, and practice the response: there is the parrot, and carrying on with what they were doing. The parrot is not argued with or shooed; it is a bird that repeats. Watch for a client who tries to teach the parrot a nicer line, which is still a conversation with the parrot.', '[{"id": "f0", "type": "textarea", "label": "The parrot''s lines, word for word, the ones it has said for years:"}, {"id": "f1", "type": "textarea", "label": "How many times it said them today, and in what situations:"}, {"id": "f2", "type": "textarea", "label": "What has changed in my life since the parrot first said them, while the words stayed the same:"}, {"id": "f3", "type": "textarea", "label": "The short response I will use: there is the parrot, and then what I return to:"}, {"id": "f4", "type": "textarea", "label": "One moment this week I heard the squawk and carried on anyway:"}, {"id": "f5", "type": "textarea", "label": "What I noticed about the parrot when I stopped answering it:"}]'::jsonb, array['defusion', 'core ACT', 'metaphor']::text[], '2026-11-18T15:00:00+00:00'::timestamptz),
  ('lighthouse-not-harbor-values-page', 'Lighthouse Not Harbor Values Page', 'act'::resource_kind, 'A values page that frames a value as a lighthouse to steer by rather than a harbor to arrive at and be done.', 'Use it to help a client who feels they keep failing at a value see it as a direction they can face at any moment.', array['Adults', 'Teens']::text[], '20 minutes', 'Clients often treat a value as a destination they have not reached, so every ordinary day becomes a shortfall. The page asks them to name a value, write what arriving at it would supposedly look like, then rewrite it as a lighthouse: a direction visible from anywhere, including from a bad week. They list three small acts that face the light today and one moment they drifted and turned back. Watch for a client who still grades themselves on distance from the harbor.', '[{"id": "f0", "type": "textarea", "label": "The value I keep feeling I have failed at:"}, {"id": "f1", "type": "textarea", "label": "What arriving at it, once and for all, would supposedly look like:"}, {"id": "f2", "type": "textarea", "label": "The same value rewritten as a direction I can face from anywhere:"}, {"id": "f3", "type": "textarea", "label": "Three small acts today that point toward the light:"}, {"id": "f4", "type": "textarea", "label": "A moment this week I drifted, and what turning back looked like:"}, {"id": "f5", "type": "textarea", "label": "What changes when there is no harbor to reach, only a direction to keep:"}]'::jsonb, array['values', 'core ACT', 'metaphor']::text[], '2026-11-18T15:00:00+00:00'::timestamptz),
  ('pebble-in-the-shoe-willingness-walk-page', 'Pebble in the Shoe Willingness Walk Page', 'act'::resource_kind, 'A willingness exercise in which the client keeps walking toward something that matters with a discomfort they cannot shake out.', 'Use it to help a client practice moving with a nagging discomfort rather than stopping to fix it first.', array['Adults', 'Teens']::text[], '20 minutes, then one week of practice', 'The page uses a pebble in the shoe for the discomfort that is real, annoying and not dangerous, the kind clients stop their whole walk to deal with. They name their pebble, note how many times this week they stopped to shake it out and what the stopping cost, then choose one short valued walk, literal or figurative, to take with the pebble still in. Afterward they record what the pebble did when it was not the main event. Watch for a client who decides their pebble is actually a broken bone; help them tell the difference.', '[{"id": "f0", "type": "textarea", "label": "My pebble: the discomfort that is real but not dangerous:"}, {"id": "f1", "type": "textarea", "label": "How often this week I stopped everything to deal with it, and what the stopping cost:"}, {"id": "f2", "type": "textarea", "label": "The short valued walk I will take with the pebble still in:"}, {"id": "f3", "type": "textarea", "label": "What I noticed about the pebble while I was walking:"}, {"id": "f4", "type": "textarea", "label": "What I noticed about the walk itself:"}, {"id": "f5", "type": "textarea", "label": "What I want to try carrying next, and how far:"}]'::jsonb, array['willingness', 'core ACT', 'metaphor']::text[], '2026-11-18T15:00:00+00:00'::timestamptz),
  ('grocery-store-narrator-noticing-page', 'Grocery Store Narrator Noticing Page', 'act'::resource_kind, 'A present-moment page that uses one grocery trip to notice the running commentary the mind adds to an ordinary errand.', 'Use it to help a client hear their mind''s narrator in a low-stakes setting and practice returning to the aisle.', array['Adults', 'Teens']::text[], 'One grocery trip, then 10 minutes', 'A grocery trip is full of narration: judgments about other shoppers, forecasts about the line, verdicts on the cart. The page asks the client to shop as usual, then write down the commentary they can remember, sort it into judging, predicting and comparing, and note how much of the trip they were in the store versus in the narration. Then they plan one more trip where they name the narrator each time and return to one sense. Watch for a client who judges the judging; that is the narrator too.', '[{"id": "f0", "type": "textarea", "label": "Lines of commentary I remember from the trip, as close to word for word as I can:"}, {"id": "f1", "type": "textarea", "label": "Sorted: which were judgments, which predictions, which comparisons:"}, {"id": "f2", "type": "textarea", "label": "Roughly how much of the trip I was in the store and how much in my head:"}, {"id": "f3", "type": "textarea", "label": "One sense I will return to next trip, such as the cold of the dairy aisle:"}, {"id": "f4", "type": "textarea", "label": "After the second trip: how often I caught the narrator, and what returning felt like:"}, {"id": "f5", "type": "textarea", "label": "Where else the same narrator shows up during my day:"}]'::jsonb, array['present moment', 'defusion', 'mindfulness']::text[], '2026-11-18T15:00:00+00:00'::timestamptz),
  ('autopilot-hour-catch-page', 'Autopilot Hour Catch Page', 'act'::resource_kind, 'A page for catching one hour a day lived on autopilot and choosing what to bring attention and values back to.', 'Use it to help a client notice where their days go missing and reclaim a small piece on purpose.', array['Adults', 'Teens']::text[], 'One week', 'Clients describe whole stretches of the day they cannot account for: the commute, the scroll, the dishes. The page asks them to identify their most reliable autopilot hour, note what the mind was doing while the body ran the routine, and decide whether that hour is fine on autopilot or is one they want back. For one they want back, they pick a single valued addition, such as a phone call during the walk or full attention on the first five minutes with the kids. Watch for a client who tries to be mindful of everything and burns out by Wednesday.', '[{"id": "f0", "type": "textarea", "label": "The hour of my day most often lived on autopilot:"}, {"id": "f1", "type": "textarea", "label": "What my mind was doing while my body ran the routine:"}, {"id": "f2", "type": "textarea", "label": "Is this hour fine on autopilot, or one I want back? Why?"}, {"id": "f3", "type": "textarea", "label": "The one valued thing I will bring to that hour this week:"}, {"id": "f4", "type": "textarea", "label": "Each day: whether I caught the hour, and what I noticed when I did:"}, {"id": "f5", "type": "textarea", "label": "Another autopilot stretch I might look at next:"}]'::jsonb, array['present moment', 'committed action', 'mindfulness']::text[], '2026-11-18T15:00:00+00:00'::timestamptz),
  ('describe-skill-for-a-photograph-card', 'Describe Skill for a Photograph Card', 'dbt'::resource_kind, 'A mindfulness card for practicing the Describe skill on a single photograph, separating what is in the frame from what the mind adds.', 'Use it to teach the difference between observing and interpreting with an object the client can hold still.', array['Adults', 'Teens', 'Groups']::text[], '10 minutes, several times a week', 'The Describe skill is hard to practice on fast-moving feelings, so the card starts with a photo. The client chooses an image, writes only what is literally visible, then writes separately what the mind supplied: who the people are, what they feel, what happened before. Then they do the same with a photo of themselves. The gap between the columns is the teaching point. In groups, swap photos and compare descriptions. Watch for evaluative words such as awkward or beautiful slipping into the first column.', '[{"id": "f0", "type": "textarea", "label": "The photo I chose, in one line:"}, {"id": "f1", "type": "textarea", "label": "Only what is literally in the frame: shapes, colors, positions, objects:"}, {"id": "f2", "type": "textarea", "label": "What my mind added: stories, feelings, meanings, judgments:"}, {"id": "f3", "type": "textarea", "label": "Words that tried to sneak into the first list but belong in the second:"}, {"id": "f4", "type": "textarea", "label": "The same two lists for a photo of myself:"}, {"id": "f5", "type": "textarea", "label": "Where in my week I could use Describe before the story takes over:"}]'::jsonb, array['core DBT', 'mindfulness', 'describe']::text[], '2026-11-18T15:00:00+00:00'::timestamptz),
  ('dear-man-for-the-neighbors-loud-music-card', 'DEAR MAN for the Neighbor''s Loud Music Card', 'dbt'::resource_kind, 'A DEAR MAN script for asking a neighbor to turn down the music, built line by line before the knock on the door.', 'Use it to help a client make a reasonable request to someone they have to keep living next to.', array['Adults']::text[], '20 minutes to plan, one conversation', 'The neighbor request is a good DEAR MAN practice because the relationship continues afterward and the client often arrives either fuming or avoiding. The card walks through Describe, Express, Assert and Reinforce, then plans staying Mindful when the neighbor gets defensive, Appearing confident at the door, and what they are willing to Negotiate, such as a cutoff time rather than silence. Rehearse the first two lines aloud in session. Watch for a client whose Describe is already an accusation.', '[{"id": "f0", "type": "textarea", "label": "Describe: the facts about the noise, with days and times, no adjectives:"}, {"id": "f1", "type": "textarea", "label": "Express: how it affects me, in one or two sentences starting with I:"}, {"id": "f2", "type": "textarea", "label": "Assert: exactly what I am asking for:"}, {"id": "f3", "type": "textarea", "label": "Reinforce: what the neighbor gets out of saying yes:"}, {"id": "f4", "type": "textarea", "label": "Mindful: what I will say if they get defensive or change the subject:"}, {"id": "f5", "type": "textarea", "label": "Appear confident: my posture, voice and the time of day I will knock:"}, {"id": "f6", "type": "textarea", "label": "Negotiate: what I could accept instead, such as a cutoff hour:"}, {"id": "f7", "type": "textarea", "label": "How it went, and what I would keep or change next time:"}]'::jsonb, array['DEAR MAN', 'interpersonal effectiveness', 'assertiveness']::text[], '2026-11-18T15:00:00+00:00'::timestamptz),
  ('opposite-action-for-envy-at-a-friends-good-news-card', 'Opposite Action for Envy at a Friend''s Good News Card', 'dbt'::resource_kind, 'An opposite action card for the sting of envy when a friend shares good news, acting toward them instead of away.', 'Use it to help a client whose envy pulls them to withdraw or undercut practice a congratulations they can stand behind.', array['Adults', 'Teens']::text[], '15 minutes, then the next piece of news', 'Envy''s action urge is to pull back, go quiet or find the flaw in the news. The card has the client name the urge honestly, check whether envy fits the facts, meaning whether the friend''s gain actually takes anything from them, and then plan the opposite: congratulating specifically, asking a question about the news, and staying in the conversation a minute longer than they want to. Afterward they rate the envy before and after acting. Watch for a client who acts opposite through gritted teeth and calls it done; the all-the-way part matters.', '[{"id": "f0", "type": "textarea", "label": "The good news and the first thing I felt and wanted to do:"}, {"id": "f1", "type": "textarea", "label": "Does the envy fit the facts? What did their gain actually take from me?"}, {"id": "f2", "type": "textarea", "label": "The specific congratulations I will give, in their words not a formula:"}, {"id": "f3", "type": "textarea", "label": "The one question about their news I will ask and listen to:"}, {"id": "f4", "type": "textarea", "label": "What I will do with my body and face so the action goes all the way:"}, {"id": "f5", "type": "textarea", "label": "Envy before and after, from 0 to 100, and what I noticed:"}]'::jsonb, array['opposite action', 'emotion regulation', 'core DBT']::text[], '2026-11-18T15:00:00+00:00'::timestamptz),
  ('pros-and-cons-of-sending-the-late-night-text-grid', 'Pros and Cons of Sending the Late Night Text Grid', 'dbt'::resource_kind, 'A pros and cons grid for the urge to send a message after midnight, weighing sending and not sending in the short and long run.', 'Use it to give a client a two-minute pause between a strong late-night urge and the send button.', array['Adults', 'Teens']::text[], '10 minutes, kept by the bed', 'The late-night text, to an ex, a friend after a fight or a boss, is a classic crisis urge: strong, time-limited and regretted by morning. The grid has four boxes, sending and not sending each in the short term and the long term, filled in ahead of time so the client has it ready when the urge arrives. They also write a rule for themselves, such as drafts are allowed but sending waits for daylight. Watch for a client who fills the grid only after sending, which still has value as a review.', '[{"id": "f0", "type": "textarea", "label": "The message I want to send, who to, and roughly what time it is:"}, {"id": "f1", "type": "textarea", "label": "Pros of sending it now, and pros of waiting until morning:"}, {"id": "f2", "type": "textarea", "label": "Cons of sending it now, and cons of waiting until morning:"}, {"id": "f3", "type": "textarea", "label": "The long-run column: how I will feel about each choice in a week:"}, {"id": "f4", "type": "textarea", "label": "My rule for late-night messages, written while calm:"}, {"id": "f5", "type": "textarea", "label": "What I did this time, and how it looked in the morning:"}]'::jsonb, array['distress tolerance', 'pros and cons', 'urges']::text[], '2026-11-18T15:00:00+00:00'::timestamptz),
  ('participate-skill-at-karaoke-night-card', 'Participate Skill at Karaoke Night Card', 'dbt'::resource_kind, 'A Participate card for throwing oneself into a karaoke night or similar silly group event without the self-watching.', 'Use it to give a client a concrete, slightly embarrassing setting to practice participating fully.', array['Adults', 'Teens', 'Groups']::text[], 'One evening, then 10 minutes', 'Participate is easiest to learn where self-consciousness is loudest, and karaoke, a dance class or charades will do. The card has the client pick the event, name what self-monitoring usually does there, choose one way to go all in, such as singing the whole song or clapping for every performer, and afterward record the moments they were fully in it versus watching themselves. The debrief asks what the watching cost and what being in it gave. Watch for a client who participates by performing for approval rather than joining.', '[{"id": "f0", "type": "textarea", "label": "The event, and what I usually do there to stay safe from embarrassment:"}, {"id": "f1", "type": "textarea", "label": "One way I will go all in this time:"}, {"id": "f2", "type": "textarea", "label": "What I will do when I catch myself watching myself from the outside:"}, {"id": "f3", "type": "textarea", "label": "Moments I was fully in it:"}, {"id": "f4", "type": "textarea", "label": "Moments I was watching myself, and what pulled me out:"}, {"id": "f5", "type": "textarea", "label": "What being all in gave me that watching never has:"}]'::jsonb, array['core DBT', 'mindfulness', 'participate']::text[], '2026-11-18T15:00:00+00:00'::timestamptz),
  ('houseguests-and-hosting-load-talk-sheet-for-partners', 'Houseguests and Hosting Load Talk Sheet for Partners', 'couples'::resource_kind, 'A talk sheet for partners to agree how long guests stay, who hosts what and what each needs to survive a full house.', 'Use it to help a couple stop fighting about visitors in the kitchen and decide the terms before the next arrival.', array['Couples']::text[], '30 minutes before a visit', 'Houseguests surface differences a couple rarely names: how long is too long, who cooks and cleans for whom, whose family gets which rules. Each partner first fills in their side alone: their ideal stay length, the hosting jobs they like and resent, and the one thing they need daily to stay sane with guests. Then they compare and write the agreement for the next visit, including a signal for I need twenty minutes. Watch for the partner whose family is visiting absorbing all the hosting out of guilt, and the other going quiet.', '[{"id": "f0", "type": "textarea", "label": "Partner A: how long a stay feels fine, and when it starts to wear on me:"}, {"id": "f1", "type": "textarea", "label": "Partner B: how long a stay feels fine, and when it starts to wear on me:"}, {"id": "f2", "type": "textarea", "label": "Partner A: the hosting jobs I am glad to do, and the ones I resent:"}, {"id": "f3", "type": "textarea", "label": "Partner B: the hosting jobs I am glad to do, and the ones I resent:"}, {"id": "f4", "type": "textarea", "label": "Each of us: the one thing I need daily to stay steady with guests in the house:"}, {"id": "f5", "type": "textarea", "label": "Our agreement for the next visit: length, jobs, and our signal for a break:"}, {"id": "f6", "type": "textarea", "label": "After the visit: what worked, and what we will change next time:"}]'::jsonb, array['couples', 'boundaries', 'family']::text[], '2026-11-18T15:00:00+00:00'::timestamptz),
  ('working-from-home-shared-space-agreement-for-partners', 'Working From Home Shared Space Agreement for Partners', 'couples'::resource_kind, 'An agreement for partners who both work from home covering noise, calls, interruptions and the end of the workday.', 'Use it to help a couple sharing a home office or kitchen table stop treating each other as coworkers they never hired.', array['Couples']::text[], '30 minutes', 'Two people working from the same rooms generate constant small frictions: a call that drowns out another, a question asked mid-focus, a workday that never visibly ends. Each partner writes their own needs for sound, space and interruptions, when their hardest focus hours fall, and what signals they are available. Then they draft the shared rules and a ritual that marks the end of work for both. Watch for the partner with the louder job assuming priority by default, and for the one who swallows every interruption and then snaps at dinner.', '[{"id": "f0", "type": "textarea", "label": "Partner A: my needs for quiet, space and uninterrupted time, and my hardest focus hours:"}, {"id": "f1", "type": "textarea", "label": "Partner B: my needs for quiet, space and uninterrupted time, and my hardest focus hours:"}, {"id": "f2", "type": "textarea", "label": "Each of us: how I will signal I am available, and how I will signal I am not:"}, {"id": "f3", "type": "textarea", "label": "Our rules for calls, headphones and who moves rooms when:"}, {"id": "f4", "type": "textarea", "label": "How we will each tell the other about a change in the day''s schedule:"}, {"id": "f5", "type": "textarea", "label": "The ritual that ends the workday for both of us:"}, {"id": "f6", "type": "textarea", "label": "After a week: the friction that remains, and the fix we will try:"}]'::jsonb, array['couples', 'boundaries', 'communication']::text[], '2026-11-18T15:00:00+00:00'::timestamptz),
  ('big-purchase-threshold-agreement-for-partners', 'Big Purchase Threshold Agreement for Partners', 'couples'::resource_kind, 'An agreement on the dollar amount above which partners check with each other before buying, and how the check happens.', 'Use it to help a couple replace surprise purchases and silent resentment with one clear rule they both wrote.', array['Couples']::text[], '30 minutes', 'Money fights often start with a purchase one partner considered routine and the other considered a conversation. The sheet has each partner name the amount at which they would want to be asked, the purchases they consider personal and exempt, and how they feel when asked or not asked. Then they settle a threshold, a way of asking that is not asking permission, and what happens with a gift or an emergency. Watch for a large income gap turning the agreement into one partner''s allowance; the threshold should feel mutual.', '[{"id": "f0", "type": "textarea", "label": "Partner A: the amount above which I would want a heads-up, and why that number:"}, {"id": "f1", "type": "textarea", "label": "Partner B: the amount above which I would want a heads-up, and why that number:"}, {"id": "f2", "type": "textarea", "label": "Each of us: purchases I consider mine alone, no check needed:"}, {"id": "f3", "type": "textarea", "label": "Each of us: how it feels to be asked, and how it feels to find out afterward:"}, {"id": "f4", "type": "textarea", "label": "Our threshold, and the words we will use to check in without asking permission:"}, {"id": "f5", "type": "textarea", "label": "How gifts, emergencies and surprises are handled:"}, {"id": "f6", "type": "textarea", "label": "In a month: how the rule has worked, and any adjustment:"}]'::jsonb, array['couples', 'money', 'decisions']::text[], '2026-11-18T15:00:00+00:00'::timestamptz),
  ('social-battery-mismatch-party-plan-for-partners', 'Social Battery Mismatch Party Plan for Partners', 'couples'::resource_kind, 'A plan for partners with different social stamina covering arrival, check-ins, a signal and how the night ends for each.', 'Use it to help a couple stop ending every party in an argument about leaving too early or staying too late.', array['Couples']::text[], '20 minutes before an event', 'One partner is warming up as the other is wilting, and the ride home is where it comes out. The sheet asks each to describe their social curve honestly, how long until they are done and what done feels like, then plan the event: arrival time, a check-in moment, a discreet signal, and options for leaving that do not require both to go, such as separate rides. Watch for the partner who stays past their limit and then punishes the other for having fun, and for the one who treats leaving as abandonment.', '[{"id": "f0", "type": "textarea", "label": "Partner A: my social curve at a party, from arrival to done, and what done feels like:"}, {"id": "f1", "type": "textarea", "label": "Partner B: my social curve at a party, from arrival to done, and what done feels like:"}, {"id": "f2", "type": "textarea", "label": "When we will arrive, and the moment we will check in with each other:"}, {"id": "f3", "type": "textarea", "label": "Our signal for I am nearly done, and what the other does when they see it:"}, {"id": "f4", "type": "textarea", "label": "Our options for leaving, including ways one of us can stay:"}, {"id": "f5", "type": "textarea", "label": "What each of us needs on the ride or walk home:"}, {"id": "f6", "type": "textarea", "label": "After the event: what worked, and what we will change for the next one:"}]'::jsonb, array['couples', 'planning', 'needs']::text[], '2026-11-18T15:00:00+00:00'::timestamptz),
  ('workday-texting-expectations-sheet-for-partners', 'Workday Texting Expectations Sheet for Partners', 'couples'::resource_kind, 'A sheet for partners to compare what they expect from messages during the workday and agree what a slow reply means.', 'Use it to help a couple whose daytime texts cause hurt feelings set expectations they can both actually meet.', array['Couples']::text[], '20 minutes', 'One partner reads an unanswered midday text as indifference; the other has not looked at their phone since nine. The sheet asks each to describe their workday access to the phone, what they like to receive during the day, what they can realistically send, and the story they tell when a reply is slow. Then they agree on what counts as urgent, how to flag it, and a line to remember when a message sits unanswered. Watch for a partner using daytime replies as a measure of love.', '[{"id": "f0", "type": "textarea", "label": "Partner A: what my workday actually allows for checking and replying:"}, {"id": "f1", "type": "textarea", "label": "Partner B: what my workday actually allows for checking and replying:"}, {"id": "f2", "type": "textarea", "label": "Each of us: what I enjoy receiving during the day, and what I can realistically send:"}, {"id": "f3", "type": "textarea", "label": "Each of us: the story I tell myself when a reply takes hours:"}, {"id": "f4", "type": "textarea", "label": "What counts as urgent for us, and how we will flag it so it is seen:"}, {"id": "f5", "type": "textarea", "label": "The line each of us will remember when a message sits unanswered:"}, {"id": "f6", "type": "textarea", "label": "After two weeks: what changed about how daytime messages feel:"}]'::jsonb, array['couples', 'communication', 'expectations']::text[], '2026-11-18T15:00:00+00:00'::timestamptz),
  ('ice-cube-melt-watch-patience-play', 'Ice Cube Melt Watch Patience Play', 'kids'::resource_kind, 'A play activity in which a child watches an ice cube melt in their hands or a bowl, practicing waiting while a feeling changes.', 'Use it to give a child a sensory picture of a big feeling that cannot be rushed but does not last.', array['Children']::text[], '15 minutes', 'The child holds an ice cube in a towel, or watches one in a warm bowl, and the parent asks what it feels like now, and now, and now. Name the parallel gently: a big feeling is cold and hard at first, and it melts on its own if we wait with it. The parent models waiting without hurrying the cube, and the child draws the cube at the start, the middle and the end. Keep it playful; some children want to race the melt, which can become a conversation about what rushing does to a feeling.', '[{"id": "f0", "type": "textarea", "label": "Draw the ice cube when we started. What did it feel like in your hands?"}, {"id": "f1", "type": "textarea", "label": "Draw it halfway. What changed, and what did we do while we waited?"}, {"id": "f2", "type": "textarea", "label": "Draw it at the end. Where did the ice go?"}, {"id": "f3", "type": "textarea", "label": "A feeling that is cold and hard at first like the ice cube:"}, {"id": "f4", "type": "textarea", "label": "What helps you wait while a big feeling melts?"}, {"id": "f5", "type": "textarea", "label": "Parent: what I noticed about my child''s waiting, and what I said to help:"}]'::jsonb, array['children', 'play', 'regulation']::text[], '2026-11-18T15:00:00+00:00'::timestamptz),
  ('paper-bag-puppet-brave-helper-craft', 'Paper Bag Puppet Brave Helper Craft', 'kids'::resource_kind, 'A craft in which a child makes a paper bag puppet who is brave and kind, then lets the puppet say the hard things first.', 'Use it to give a child a character who can voice worries and brave plans when speaking as themselves is too much.', array['Children']::text[], '30 minutes', 'Children often say through a puppet what they cannot say directly. The child decorates a lunch bag puppet, names it, and decides what makes it brave and what it is still learning. The parent talks to the puppet, asks it what it worries about and what it does when scared, and lets the child answer in the puppet''s voice without correcting. Keep the puppet in the room for later sessions. Watch for a parent who turns the puppet into a lecture about being brave rather than a listener.', '[{"id": "f0", "type": "textarea", "label": "My puppet''s name, and three things that make it brave:"}, {"id": "f1", "type": "textarea", "label": "One thing my puppet is still learning to be brave about:"}, {"id": "f2", "type": "textarea", "label": "What my puppet says when it feels scared:"}, {"id": "f3", "type": "textarea", "label": "What my puppet would tell a kid who feels the same way:"}, {"id": "f4", "type": "textarea", "label": "Draw my puppet doing something brave this week:"}, {"id": "f5", "type": "textarea", "label": "Parent: what my child said through the puppet that they had not said before:"}]'::jsonb, array['children', 'craft', 'externalizing']::text[], '2026-11-18T15:00:00+00:00'::timestamptz),
  ('nature-walk-five-calm-treasures-collect-play', 'Nature Walk Five Calm Treasures Collect Play', 'kids'::resource_kind, 'A walk during which a child collects five small natural things that feel calm to hold, then builds a calm shelf at home.', 'Use it to help a child find grounding objects outdoors and practice slowing down with their hands and eyes.', array['Children']::text[], '30 minute walk, then 15 minutes at home', 'The parent and child take a slow walk with a small bag and look for five things that feel calm to hold: a smooth stone, a pinecone, a feather, a soft leaf. The parent narrates noticing out loud and asks the child what each treasure feels like in their hand. At home the five go on a shelf or in a box the child labels, and the child chooses which one to hold when feelings get big. Watch for a parent who turns it into a hurried errand; the slowness is the exercise.', '[{"id": "f0", "type": "textarea", "label": "Draw or list my five calm treasures:"}, {"id": "f1", "type": "textarea", "label": "For each one: what it feels like in my hand, and where I found it:"}, {"id": "f2", "type": "textarea", "label": "The treasure I will hold when a feeling gets big:"}, {"id": "f3", "type": "textarea", "label": "Where my calm shelf or box lives at home:"}, {"id": "f4", "type": "textarea", "label": "What was the slowest part of the walk, and what did I notice there?"}, {"id": "f5", "type": "textarea", "label": "Parent: how the pace of the walk felt, and what my child noticed that I missed:"}]'::jsonb, array['children', 'grounding', 'play']::text[], '2026-11-18T15:00:00+00:00'::timestamptz),
  ('mood-dot-sticker-daily-check-chart-craft', 'Mood Dot Sticker Daily Check Chart Craft', 'kids'::resource_kind, 'A chart a child makes with colored dot stickers to mark how they feel morning and night, read together each week.', 'Use it to help a child and parent notice feeling patterns across a week without a conversation at every moment.', array['Children']::text[], '20 minutes to make, one week to use', 'The child draws a week grid and chooses which color dot means which feeling, with a legend they design. Morning and bedtime they place a dot, and the parent asks nothing more than which color and, if the child offers, why. At the end of the week they read the chart together like detectives, looking for days with a lot of one color and what was happening. Watch for a parent who treats the chart as a report card or presses for reasons at the moment of placing the dot.', '[{"id": "f0", "type": "textarea", "label": "My color legend: which color means which feeling:"}, {"id": "f1", "type": "textarea", "label": "Draw my week grid with a morning box and a bedtime box for each day:"}, {"id": "f2", "type": "textarea", "label": "At the end of the week: which color showed up most, and on which days?"}, {"id": "f3", "type": "textarea", "label": "What was happening on the days with the hardest colors?"}, {"id": "f4", "type": "textarea", "label": "What was happening on the days with the best colors?"}, {"id": "f5", "type": "textarea", "label": "Parent: one pattern we found together, and what we will try next week:"}]'::jsonb, array['children', 'craft', 'emotion identification']::text[], '2026-11-18T15:00:00+00:00'::timestamptz),
  ('playdough-squeeze-and-shape-a-feeling-play', 'Playdough Squeeze and Shape a Feeling Play', 'kids'::resource_kind, 'A play activity in which a child squeezes playdough to let a big feeling out through their hands, then shapes what it became.', 'Use it to give a child a physical outlet for a feeling and a way to show it changing in their hands.', array['Children']::text[], '15 minutes', 'The child picks a color for the feeling, squeezes and pounds the dough as hard as the feeling is, and the parent matches the energy without commentary. When the squeezing slows, the parent asks what the feeling looks like now and the child shapes it into something. The shape often changes from a spiky thing to a calmer one, and that is the teaching. Keep the dough available at home for a repeat. Watch for a parent who asks the child to use words before the hands are done.', '[{"id": "f0", "type": "textarea", "label": "The color I picked for my feeling, and how big it was:"}, {"id": "f1", "type": "textarea", "label": "What my hands did with the dough while the feeling was biggest:"}, {"id": "f2", "type": "textarea", "label": "Draw the shape I made when my hands slowed down:"}, {"id": "f3", "type": "textarea", "label": "What the shape would say if it could talk:"}, {"id": "f4", "type": "textarea", "label": "Where I will keep my dough for the next big feeling:"}, {"id": "f5", "type": "textarea", "label": "Parent: what I did alongside my child, and when I knew the feeling had shifted:"}]'::jsonb, array['children', 'play', 'regulation']::text[], '2026-11-18T15:00:00+00:00'::timestamptz),
  ('a-to-z-gratitude-race-game', 'A to Z Gratitude Race Game', 'game'::resource_kind, 'A fast group game in which teams race to name something they are grateful for starting with each letter of the alphabet.', 'Use it to warm up a group with quick, specific gratitude and a bit of friendly competition.', array['Groups', 'Teens', 'Adults']::text[], '15 minutes', 'Split into two or three teams, each with a sheet listing A to Z. On go, teams fill in one specific thing they are grateful for per letter; vague answers like good things do not count, and the facilitator may challenge. First team to finish, or most letters in eight minutes, wins. Debrief by having each team read their hardest letter and the easiest, and ask which answers surprised the people who wrote them. Watch for a team where one person writes everything; require rotating pens.', '[{"id": "f0", "type": "textarea", "label": "Our team''s hardest letter, and what we finally came up with:"}, {"id": "f1", "type": "textarea", "label": "The answer on our sheet that surprised me most:"}, {"id": "f2", "type": "textarea", "label": "An answer another team gave that I wish I had thought of:"}, {"id": "f3", "type": "textarea", "label": "A letter I would fill in differently if I did it alone:"}, {"id": "f4", "type": "textarea", "label": "One thing from the sheet I will tell the person it is about:"}]'::jsonb, array['game', 'gratitude', 'group']::text[], '2026-11-18T15:00:00+00:00'::timestamptz),
  ('paper-airplane-question-flight-game', 'Paper Airplane Question Flight Game', 'game'::resource_kind, 'A group game in which each person writes a question on a paper airplane, flies it, and answers whichever one lands near them.', 'Use it to get a quiet group talking with questions nobody has to own out loud.', array['Groups', 'Teens', 'Adults']::text[], '20 minutes', 'Everyone writes one question they would like the group to answer on a sheet of paper, folds it into an airplane, and on the count of three all planes fly. Each person picks up the nearest plane and answers its question in turn; passing is allowed once. Fly a second round if time allows. Debrief on which questions came up more than once and what that says about what the group is wondering. Watch for a question that targets a member, and set the rule up front that questions are for anyone.', '[{"id": "f0", "type": "textarea", "label": "The question I wrote on my plane, and why I wanted it asked:"}, {"id": "f1", "type": "textarea", "label": "The question that landed near me, and what I answered:"}, {"id": "f2", "type": "textarea", "label": "An answer from someone else that stayed with me:"}, {"id": "f3", "type": "textarea", "label": "A question that came up more than once in the room:"}, {"id": "f4", "type": "textarea", "label": "A question I would write for the next round:"}]'::jsonb, array['game', 'icebreaker', 'group']::text[], '2026-11-18T15:00:00+00:00'::timestamptz),
  ('shoe-pile-owner-icebreaker-game', 'Shoe Pile Owner Icebreaker Game', 'game'::resource_kind, 'An icebreaker in which everyone puts one shoe in a pile, draws someone else''s, and finds the owner to ask them three questions.', 'Use it to pair up strangers in a group quickly and give them a reason to talk.', array['Groups', 'Teens', 'Adults']::text[], '15 minutes', 'Each member adds one shoe to a pile in the center, then draws a shoe that is not theirs and finds its owner. The pair takes turns asking three questions from a list the facilitator posts, such as what brought you here and what you are hoping for. After five minutes each person introduces their partner to the group by shoe and one fact. Debrief on how it felt to be found versus to search. Watch for a member uncomfortable removing a shoe; allow any personal item instead.', '[{"id": "f0", "type": "textarea", "label": "The shoe or item I drew, and how long it took to find its owner:"}, {"id": "f1", "type": "textarea", "label": "The three questions I asked, and the answer I remember best:"}, {"id": "f2", "type": "textarea", "label": "One fact about my partner I will share with the group:"}, {"id": "f3", "type": "textarea", "label": "How it felt to search, and how it felt to be found:"}, {"id": "f4", "type": "textarea", "label": "Someone else in the room I would like to ask the same questions:"}]'::jsonb, array['game', 'icebreaker', 'group']::text[], '2026-11-18T15:00:00+00:00'::timestamptz),
  ('three-legged-walk-teamwork-game', 'Three-Legged Walk Teamwork Game', 'game'::resource_kind, 'A pairs game in which two people with a leg tied together walk a short course, coordinating pace and steps out loud.', 'Use it to show a group what cooperation under mild frustration actually feels like in the body.', array['Groups', 'Teens', 'Children']::text[], '20 minutes', 'Pairs tie adjacent legs together with a soft scarf and walk a short course with one or two turns. The first round is silent; the second allows talking; the third has pairs agree on a rhythm before starting. Time each round. Debrief on which round went best and why, what each partner did when the other stumbled, and who adjusted to whom. Watch for a pair in which one person drags the other and calls it leading. Check for mobility needs and offer a hand-holding version.', '[{"id": "f0", "type": "textarea", "label": "Our times for the silent round, the talking round and the planned round:"}, {"id": "f1", "type": "textarea", "label": "What my partner did that helped, and what made it harder:"}, {"id": "f2", "type": "textarea", "label": "What I did when one of us stumbled:"}, {"id": "f3", "type": "textarea", "label": "Who adjusted to whom, and how we decided:"}, {"id": "f4", "type": "textarea", "label": "A place in my life where I am walking three-legged with someone right now:"}]'::jsonb, array['game', 'group', 'communication']::text[], '2026-11-18T15:00:00+00:00'::timestamptz),
  ('interview-and-introduce-your-partner-game', 'Interview and Introduce Your Partner Game', 'game'::resource_kind, 'A pairs game in which each person interviews a partner for three minutes and then introduces them to the group in first person.', 'Use it to practice listening closely enough to speak as someone else, and to let shy members be introduced rather than introduce themselves.', array['Groups', 'Teens', 'Adults']::text[], '25 minutes', 'Pairs take turns interviewing each other for three minutes with a few posted questions, no notes allowed. Then each person stands and introduces their partner in the first person, as if they were them: My name is, and I came here because. The partner may correct one detail afterward. Debrief on what it was like to be spoken for accurately, what was missed, and what people chose to share versus hold back. Watch for a member who embellishes for laughs at the partner''s expense.', '[{"id": "f0", "type": "textarea", "label": "The questions I asked my partner, and what I remembered without notes:"}, {"id": "f1", "type": "textarea", "label": "What it was like to hear myself introduced in my own voice by someone else:"}, {"id": "f2", "type": "textarea", "label": "The one detail I corrected, or wanted to:"}, {"id": "f3", "type": "textarea", "label": "What I chose to share in the interview, and what I kept back:"}, {"id": "f4", "type": "textarea", "label": "What I noticed about how closely I listened compared to usual:"}]'::jsonb, array['game', 'listening', 'group']::text[], '2026-11-18T15:00:00+00:00'::timestamptz),
  ('anniversary-week-steadiness-plan-sheet', 'Anniversary Week Steadiness Plan Sheet', 'worksheet'::resource_kind, 'A plan for the week around the anniversary of a hard event covering sleep, company, workload and what the client will not do that week.', 'Use it to help a client meet a known hard week with a plan made while steady rather than in the middle of it.', array['Adults', 'Teens']::text[], '30 minutes, two weeks before the date', 'Anniversaries tend to arrive before the date on the calendar, in sleep and mood and startle. The sheet asks the client to mark the week, name the early signs they have noticed in past years, decide who will know and what they are asking of those people, lighten the schedule on purpose, and list grounding tools they already trust. It also asks what they will not do that week, such as watching the news coverage. This is a steadiness plan, not a retelling; keep the event itself to a word or two. Review the plan the session after the date passes.', '[{"id": "f0", "type": "textarea", "label": "The date, and the days before and after when I usually start to feel it:"}, {"id": "f1", "type": "textarea", "label": "The early signs from past years: sleep, mood, body, startle:"}, {"id": "f2", "type": "textarea", "label": "Who will know it is that week, and what exactly I am asking of them:"}, {"id": "f3", "type": "textarea", "label": "What I will take off my schedule, and what I will keep because it steadies me:"}, {"id": "f4", "type": "textarea", "label": "The grounding tools I already trust, and where they will be within reach:"}, {"id": "f5", "type": "textarea", "label": "What I will not do that week, and what I will do instead:"}, {"id": "f6", "type": "textarea", "label": "After the week: what helped most, for next year''s plan:"}]'::jsonb, array['PTSD and trauma', 'stabilizing', 'planning']::text[], '2026-11-18T15:00:00+00:00'::timestamptz),
  ('startle-at-the-doorbell-thought-check-sheet', 'Startle at the Doorbell Thought Check Sheet', 'cbt'::resource_kind, 'A thought check for the moment after a big startle at an ordinary sound, catching the verdict that jumping means being broken.', 'Use it to help a client separate a fast body reflex from the story they tell about themselves afterward.', array['Adults', 'Teens']::text[], '10 minutes after a startle', 'A doorbell, a dropped pan or a car door can produce a full-body jolt, and many clients add a second injury: I am never going to be normal. The sheet captures the sound, the body''s response, the thought that followed, and then separates reflex from meaning, asking what a startle reflex is for and what it says and does not say about the person. It ends with one grounding step and a kinder line. Keep the focus on the present-day sound, not on the original event. Watch for a client who avoids places with sudden noises; that belongs in a separate plan.', '[{"id": "f0", "type": "textarea", "label": "The sound, where I was and what my body did in the first second:"}, {"id": "f1", "type": "textarea", "label": "The thought that came right after, word for word:"}, {"id": "f2", "type": "textarea", "label": "What a startle reflex is for, and what it proves about me as a person:"}, {"id": "f3", "type": "textarea", "label": "What I would say to a friend whose body jumped the same way:"}, {"id": "f4", "type": "textarea", "label": "A fairer line to have ready for the next startle:"}, {"id": "f5", "type": "textarea", "label": "The grounding step I took, or will take, once my heart slows:"}]'::jsonb, array['PTSD and trauma', 'thinking traps', 'self-talk']::text[], '2026-11-18T15:00:00+00:00'::timestamptz),
  ('safe-enough-to-rest-ten-minutes-willingness-page', 'Safe Enough to Rest Ten Minutes Willingness Page', 'act'::resource_kind, 'A willingness page for letting the guard down for ten minutes in a place the client has already judged safe enough.', 'Use it to help a client who is always on watch practice brief, chosen rest without waiting to feel fully safe first.', array['Adults', 'Teens']::text[], '20 minutes, then ten minutes daily', 'Clients who scan every room rarely rest because rest waits for a certainty that never arrives. The page asks them to choose one spot they have already judged safe enough, a time, a timer, and what they will do with their hands and eyes for ten minutes. They note the thoughts that will object and agree to let them object without obeying. Afterward they record what the body did in the ten minutes and what the mind predicted versus what happened. This is willingness in a place already deemed safe, not a test of danger. Watch for a client who picks a spot that is not actually safe for them.', '[{"id": "f0", "type": "textarea", "label": "The spot I have already judged safe enough, and why:"}, {"id": "f1", "type": "textarea", "label": "The time of day, and how I will set the ten minutes:"}, {"id": "f2", "type": "textarea", "label": "What my hands and eyes will do while I rest:"}, {"id": "f3", "type": "textarea", "label": "The thoughts that will object, written in advance:"}, {"id": "f4", "type": "textarea", "label": "What my body did during the ten minutes:"}, {"id": "f5", "type": "textarea", "label": "What the mind predicted, and what actually happened:"}, {"id": "f6", "type": "textarea", "label": "Whether I want eleven minutes tomorrow, or ten again:"}]'::jsonb, array['PTSD and trauma', 'willingness', 'grounding']::text[], '2026-11-18T15:00:00+00:00'::timestamptz),
  ('five-textures-within-reach-grounding-card', 'Five Textures Within Reach Grounding Card', 'dbt'::resource_kind, 'A grounding card that uses touch alone: five textures within arm''s reach, named and described, to return attention to now.', 'Use it to give a client a grounding skill that works with eyes down in a waiting room, a car or a meeting.', array['Adults', 'Teens', 'Groups']::text[], 'Two minutes, practiced daily', 'Sight-based grounding is hard when a client cannot look around without drawing attention. The card has them find five textures within reach, the chair arm, a sleeve, a key, the table edge, a zipper, and describe each to themselves in plain words: rough, cool, ridged. Practice in session with eyes down so the client knows it works unseen. Have them pre-plan the five for the places they most often feel pulled back, such as the car at a light. Watch for a client who rushes the five; the describing is the skill, not the counting.', '[{"id": "f0", "type": "textarea", "label": "Five textures within reach right now, described in plain words:"}, {"id": "f1", "type": "textarea", "label": "The place I most often get pulled back, and five textures that are always there:"}, {"id": "f2", "type": "textarea", "label": "The texture that brought me back fastest, and why I think it worked:"}, {"id": "f3", "type": "textarea", "label": "Something I could carry in a pocket so there is always a sixth:"}, {"id": "f4", "type": "textarea", "label": "When I used the card this week, and what came after it:"}]'::jsonb, array['PTSD and trauma', 'grounding', 'distress tolerance']::text[], '2026-11-18T15:00:00+00:00'::timestamptz),
  ('brave-pocket-pebble-painting-craft', 'Brave Pocket Pebble Painting Craft', 'kids'::resource_kind, 'A craft in which a child paints a small smooth pebble to carry in a pocket as a reminder of a safe person and a steady feeling.', 'Use it to give a child something to hold at school or bedtime that stands for the grown-ups and places that keep them safe.', array['Children']::text[], '30 minutes', 'The child chooses a pebble that fits their hand, paints it in colors that feel calm, and adds a tiny symbol for a safe grown-up or place. The parent helps seal it and talks about when a pocket pebble helps: a new room, a loud place, a hard goodbye. Practice holding it with a slow breath so the pebble and the breath pair up. This is a steadying object, not a prompt for talking about what happened; follow the child''s lead. If a child discloses during the activity, remember your reporting duties and respond calmly.', '[{"id": "f0", "type": "textarea", "label": "Draw my pebble and the colors I chose:"}, {"id": "f1", "type": "textarea", "label": "The safe grown-up or place my pebble reminds me of:"}, {"id": "f2", "type": "textarea", "label": "Times when I will hold my pebble in my pocket:"}, {"id": "f3", "type": "textarea", "label": "What I do with my breathing while I hold it:"}, {"id": "f4", "type": "textarea", "label": "Parent: where the pebble lives so it is not lost, and when we practiced holding it:"}]'::jsonb, array['PTSD and trauma', 'children', 'grounding']::text[], '2026-11-18T15:00:00+00:00'::timestamptz),
  ('rsvp-yes-then-cancel-pattern-sheet', 'RSVP Yes Then Cancel Pattern Sheet', 'worksheet'::resource_kind, 'A sheet that tracks the cycle of saying yes to plans while calm and canceling as the date nears, with the cost on both sides.', 'Use it to help a client see their commit-then-cancel pattern on paper and choose where to break it.', array['Adults', 'Teens']::text[], 'Two weeks of logging, then 20 minutes', 'The client logs each invitation for two weeks: when they said yes, how anxious they were at the yes, how anxious the day before, whether they went, and the reason they gave if they canceled. Then they add two columns the pattern hides: what canceling cost them and the other person, and how the event actually went when they attended. Watch for a client whose yes is automatic and whose cancellation is the real answer; that may call for honest noes rather than more attendance. Pick one upcoming event to keep.', '[{"id": "f0", "type": "textarea", "label": "Each invitation: when I said yes, and my anxiety at that moment from 0 to 100:"}, {"id": "f1", "type": "textarea", "label": "My anxiety the day before, and whether I went or canceled:"}, {"id": "f2", "type": "textarea", "label": "The reasons I gave when I canceled, and the real reason:"}, {"id": "f3", "type": "textarea", "label": "What canceling cost me, and what it cost the person who invited me:"}, {"id": "f4", "type": "textarea", "label": "How the events I attended actually went compared to what I expected:"}, {"id": "f5", "type": "textarea", "label": "One upcoming event I will keep, and what I will do with the anxiety the day before:"}]'::jsonb, array['anxiety', 'avoidance', 'self-monitoring']::text[], '2026-11-18T15:00:00+00:00'::timestamptz),
  ('boss-said-can-we-talk-tomorrow-thought-record', 'Boss Said Can We Talk Tomorrow Thought Record', 'cbt'::resource_kind, 'A thought record for the night after a manager asks for a meeting with no detail, catching the certainty that it is bad news.', 'Use it to help a client get through an evening of not knowing without rehearsing the worst version all night.', array['Adults']::text[], '15 minutes that evening', 'A vague meeting request is a reliable mind-reading trigger. The record has the client write what was actually said, the meaning they attached, their emotion and its strength, the full range of reasons a manager might ask for a word, evidence about this manager''s habits, and a plan for the evening that is not rehearsal. The follow-up prompt, filled in after the meeting, is the most useful part over time. Watch for a client who spends the night drafting a defense; name it as a safety behavior.', '[{"id": "f0", "type": "textarea", "label": "What my manager actually said, word for word, and how they said it:"}, {"id": "f1", "type": "textarea", "label": "The meaning I attached, and how certain I felt from 0 to 100:"}, {"id": "f2", "type": "textarea", "label": "What I felt, and how strongly:"}, {"id": "f3", "type": "textarea", "label": "Every reason a manager might ask for a word tomorrow, bad, neutral and good:"}, {"id": "f4", "type": "textarea", "label": "What I know about this manager''s habits and past meetings like this:"}, {"id": "f5", "type": "textarea", "label": "What I will do with tonight instead of rehearsing:"}, {"id": "f6", "type": "textarea", "label": "After the meeting: what it was actually about, and what I will remember next time:"}]'::jsonb, array['anxiety', 'thought record', 'uncertainty']::text[], '2026-11-18T15:00:00+00:00'::timestamptz),
  ('overeager-intern-mind-defusion-page', 'Overeager Intern Mind Defusion Page', 'act'::resource_kind, 'A defusion page that casts the anxious mind as an overeager intern who brings far too many memos and means well.', 'Use it to help a client relate to anxious thoughts with patience and a little humor instead of alarm.', array['Adults', 'Teens']::text[], '15 minutes, then daily', 'The page frames the mind as a new intern who has decided the client''s survival depends on flagging everything. The client lists the memos the intern delivered today, notices the tone, thanks the intern for the effort, and decides which memos deserve a real action and which get filed. The point is warmth toward the mind rather than a fight with it. Have the client practice the thank-you line aloud. Watch for a client who fires the intern, meaning tries to suppress the thoughts; the intern does not take dismissal well.', '[{"id": "f0", "type": "textarea", "label": "The memos my intern delivered today, in one line each:"}, {"id": "f1", "type": "textarea", "label": "The tone of the memos: urgent, apologetic, repetitive, dramatic:"}, {"id": "f2", "type": "textarea", "label": "The thank-you line I will use when the intern bursts in:"}, {"id": "f3", "type": "textarea", "label": "Which memos get a real action today, and which get filed:"}, {"id": "f4", "type": "textarea", "label": "What I noticed about the intern when I stopped arguing with the memos:"}, {"id": "f5", "type": "textarea", "label": "What the intern is actually trying to protect, in one sentence:"}]'::jsonb, array['anxiety', 'defusion', 'metaphor']::text[], '2026-11-18T15:00:00+00:00'::timestamptz),
  ('wise-mind-before-canceling-plans-card', 'Wise Mind Before Canceling Plans Card', 'dbt'::resource_kind, 'A Wise Mind card for the hour before canceling a plan, hearing out emotion mind and reasonable mind before choosing.', 'Use it to give a client a pause between the urge to cancel and the text that does it.', array['Adults', 'Teens']::text[], '10 minutes before deciding', 'The urge to cancel usually arrives with a convincing reason and a short deadline. The card has the client write what emotion mind says, what reasonable mind says, and then sit for two slow breaths and write what wise mind knows about this plan, this person and this pattern. They decide, go or cancel, and either way note how the decision felt an hour later. Canceling can be the wise choice; the card is about who chooses. Watch for a client whose reasonable mind is just emotion mind with a spreadsheet.', '[{"id": "f0", "type": "textarea", "label": "The plan, and the moment the urge to cancel showed up:"}, {"id": "f1", "type": "textarea", "label": "What emotion mind says, in its own words:"}, {"id": "f2", "type": "textarea", "label": "What reasonable mind says:"}, {"id": "f3", "type": "textarea", "label": "After two slow breaths: what wise mind knows about this plan and this pattern:"}, {"id": "f4", "type": "textarea", "label": "What I decided, and how I let the other person know:"}, {"id": "f5", "type": "textarea", "label": "An hour later: how the decision sits with me:"}]'::jsonb, array['anxiety', 'wise mind', 'core DBT']::text[], '2026-11-18T15:00:00+00:00'::timestamptz),
  ('guess-the-outcome-worry-reveal-game', 'Guess the Outcome Worry Reveal Game', 'game'::resource_kind, 'A group game in which members share an old worry, others guess how it turned out, and the real ending is revealed.', 'Use it to show a group how rarely worries come true in the shape they were feared, using their own histories.', array['Groups', 'Teens', 'Adults']::text[], '25 minutes', 'Each member writes a worry from the past on a card, something they fretted about that has since resolved, without the ending. Cards are drawn one at a time, the group votes on how it ended, worse than feared, about as feared or better than feared, and the writer reveals the real outcome and how long the worry lasted. Tally the votes against reality on a board. Debrief on which outcome came up most and what the room learned about its own forecasts. Keep crisis-level worries out of the deck; say so when setting up.', '[{"id": "f0", "type": "textarea", "label": "The old worry I wrote on my card, and the ending I did not write:"}, {"id": "f1", "type": "textarea", "label": "How the group voted on my worry, and how it actually went:"}, {"id": "f2", "type": "textarea", "label": "The tally on the board: worse, as feared or better, across the room:"}, {"id": "f3", "type": "textarea", "label": "A worry someone else shared that sounded like one of mine:"}, {"id": "f4", "type": "textarea", "label": "A current worry I would put in the deck a year from now, and my honest guess at its ending:"}]'::jsonb, array['anxiety', 'game', 'predictions']::text[], '2026-11-18T15:00:00+00:00'::timestamptz),
  ('plants-pets-and-people-small-care-chain-sheet', 'Plants Pets and People Small Care Chain Sheet', 'worksheet'::resource_kind, 'A sheet that links one small act of care for a plant, a pet or a person to the client''s own day on low days.', 'Use it to help a client who cannot do things for themselves yet find a foothold in caring for something small.', array['Adults', 'Teens']::text[], 'One week', 'On low days, caring for the self can feel impossible while caring for a plant on the windowsill still feels doable. The sheet asks the client to pick one living thing to tend daily, then chain one small self-care act to it: water the plant, drink a glass of water; feed the cat, eat something; text a friend, open the curtains. They log the chain each day and note what happened to the second link. Watch for a client who tends everything else and still skips the second link; make it smaller. Never let the chain become another failure to log.', '[{"id": "f0", "type": "textarea", "label": "The plant, pet or person I will tend each day this week:"}, {"id": "f1", "type": "textarea", "label": "The small act for myself I will chain to it:"}, {"id": "f2", "type": "textarea", "label": "Each day: did the first link happen, and did the second follow?"}, {"id": "f3", "type": "textarea", "label": "What got in the way of the second link on the days it did not:"}, {"id": "f4", "type": "textarea", "label": "How the living thing I tended is doing at the end of the week:"}, {"id": "f5", "type": "textarea", "label": "How I am doing, in one honest line:"}]'::jsonb, array['depression', 'behavioral activation', 'self-care']::text[], '2026-11-18T15:00:00+00:00'::timestamptz),
  ('i-ruined-the-evening-with-my-mood-thought-record', 'I Ruined the Evening With My Mood Thought Record', 'cbt'::resource_kind, 'A thought record for the guilt after a quiet evening with others, catching the belief that low mood spoiled it for everyone.', 'Use it to help a client check the story that their mood is a burden others are silently resenting.', array['Adults', 'Teens']::text[], '15 minutes', 'Clients with low mood often leave a gathering convinced they dragged it down, and the conviction keeps them from the next one. The record captures the evening, the thought, the feeling, what they actually observed others doing, what others have said when asked directly, and a fairer account that leaves room for having been quiet without having ruined anything. Encourage a reality check with one trusted person. Watch for personalization, the sense that every lull in the room was about them.', '[{"id": "f0", "type": "textarea", "label": "The evening, who was there and what I did and did not do:"}, {"id": "f1", "type": "textarea", "label": "The thought on the way home, word for word:"}, {"id": "f2", "type": "textarea", "label": "The feeling and its strength from 0 to 100:"}, {"id": "f3", "type": "textarea", "label": "What I actually saw others doing and saying during the evening:"}, {"id": "f4", "type": "textarea", "label": "What people have said when I have asked them directly, now or in the past:"}, {"id": "f5", "type": "textarea", "label": "A fairer account of my part in the evening:"}, {"id": "f6", "type": "textarea", "label": "One person I could ask about it, and what I will ask:"}]'::jsonb, array['depression', 'thought record', 'thinking traps']::text[], '2026-11-18T15:00:00+00:00'::timestamptz),
  ('gray-lens-on-the-camera-defusion-page', 'Gray Lens on the Camera Defusion Page', 'act'::resource_kind, 'A defusion page that treats low mood as a gray filter over the camera, changing how everything looks without changing what is there.', 'Use it to help a client hold their bleak conclusions as the lens''s work rather than as the truth about their life.', array['Adults', 'Teens']::text[], '15 minutes', 'Low mood does not just feel bad; it colors every judgment, and clients make decisions through the gray without knowing it. The page asks them to list conclusions they reached today, mark which ones were filmed through the lens, recall how the same scenes looked on a clearer day, and decide which decisions can wait until the lens lifts. The lens is not argued with; it is named. Watch for a client who uses the lens idea to dismiss real problems; some gray conclusions are also accurate, and the page lets them sort.', '[{"id": "f0", "type": "textarea", "label": "Conclusions I reached today about myself, my life or other people:"}, {"id": "f1", "type": "textarea", "label": "Which of these were filmed through the gray lens, and how I can tell:"}, {"id": "f2", "type": "textarea", "label": "How the same scenes looked on a clearer day I can remember:"}, {"id": "f3", "type": "textarea", "label": "Decisions I will put off until the lens lifts, and ones that can be made in the gray:"}, {"id": "f4", "type": "textarea", "label": "The words I will use when I notice the lens: There is the filter again:"}, {"id": "f5", "type": "textarea", "label": "One thing I did today that the lens told me was pointless:"}]'::jsonb, array['depression', 'defusion', 'metaphor']::text[], '2026-11-18T15:00:00+00:00'::timestamptz),
  ('participate-in-the-walk-without-the-commentary-card', 'Participate in the Walk Without the Commentary Card', 'dbt'::resource_kind, 'A Participate card for a short daily walk taken fully, with the mind''s commentary on pointlessness noticed and set down.', 'Use it to pair a behavioral step with a mindfulness skill so the walk is more than a box ticked.', array['Adults', 'Teens']::text[], 'Ten minute walk daily for one week', 'Clients with low mood often do the recommended walk while narrating its uselessness, and come back having had the narration rather than the walk. The card asks for a ten minute route, a single sense to throw themselves into, feet on pavement or air on the face, and a phrase for the commentary when it starts. Afterward they note minutes spent in the walk versus in the commentary, and mood before and after. Watch for a client grading each walk, which is commentary by another name.', '[{"id": "f0", "type": "textarea", "label": "My ten minute route, and the time of day:"}, {"id": "f1", "type": "textarea", "label": "The sense I will throw myself into on the walk:"}, {"id": "f2", "type": "textarea", "label": "What I will say to the commentary when it starts:"}, {"id": "f3", "type": "textarea", "label": "Each day: minutes in the walk versus minutes in the commentary, roughly:"}, {"id": "f4", "type": "textarea", "label": "Mood before and after each walk, from 0 to 10:"}, {"id": "f5", "type": "textarea", "label": "What I noticed on the route that I had not noticed before:"}]'::jsonb, array['depression', 'core DBT', 'mindfulness']::text[], '2026-11-18T15:00:00+00:00'::timestamptz),
  ('saturday-walk-standing-invitation-for-partners', 'Saturday Walk Standing Invitation for Partners', 'couples'::resource_kind, 'An agreement between partners for a standing Saturday walk that is always offered and never pressured on low weeks.', 'Use it to help a couple keep one gentle, predictable shared activity through a stretch of one partner''s low mood.', array['Couples']::text[], '20 minutes to agree, weekly to use', 'A partner with low mood often declines everything, and the other partner stops asking to avoid rejection. The sheet sets up one standing invitation: the same walk, the same time, offered every week in the same words. The low partner writes what makes accepting easier and what the no will sound like when it is a no; the other writes how they will offer without pressure and what they will do with their own disappointment. Both agree the invitation survives any number of noes. Watch for the offer turning into a test.', '[{"id": "f0", "type": "textarea", "label": "Partner A: the walk, the time, and the exact words I will use to offer it:"}, {"id": "f1", "type": "textarea", "label": "Partner B: what makes it easier for me to say yes, such as no talking required:"}, {"id": "f2", "type": "textarea", "label": "Partner B: what my no will sound like when it is a real no, so there is no guessing:"}, {"id": "f3", "type": "textarea", "label": "Partner A: what I will do with my disappointment on the weeks the answer is no:"}, {"id": "f4", "type": "textarea", "label": "Our agreement that the invitation survives every no:"}, {"id": "f5", "type": "textarea", "label": "After a month: how many walks happened, and what they were like:"}]'::jsonb, array['depression', 'couples', 'support']::text[], '2026-11-18T15:00:00+00:00'::timestamptz),
  ('subscriptions-and-auto-renewals-audit-sheet', 'Subscriptions and Auto-Renewals Audit Sheet', 'worksheet'::resource_kind, 'An audit of every subscription and auto-renewal the client is paying for, found by reading the statement, with a decision on each.', 'Use it to help a client who signs up and forgets reclaim money and the sense of being on top of things.', array['Adults', 'Teens']::text[], '45 minutes, once', 'Forgotten subscriptions are a quiet tax on clients who start things with enthusiasm and lose track. The sheet asks them to read the last two months of statements line by line, list every recurring charge, mark each as used, forgotten or not sure, and decide keep, cancel or set a reminder. It adds a step many skip: writing down where to cancel and doing one in session. Watch for a client who feels so ashamed of the total that they stop halfway; frame the total as money found, not money lost.', '[{"id": "f0", "type": "textarea", "label": "Every recurring charge on the last two statements, with the amount:"}, {"id": "f1", "type": "textarea", "label": "For each: used regularly, forgotten, or not sure what it is:"}, {"id": "f2", "type": "textarea", "label": "The monthly total, and how that number feels to see:"}, {"id": "f3", "type": "textarea", "label": "Keep, cancel or set a reminder, for each one:"}, {"id": "f4", "type": "textarea", "label": "The first one I will cancel, where to do it, and whether I did it now:"}, {"id": "f5", "type": "textarea", "label": "A rule for future sign-ups so this list stays short:"}]'::jsonb, array['ADHD', 'executive function', 'money']::text[], '2026-11-18T15:00:00+00:00'::timestamptz),
  ('if-i-start-i-have-to-finish-tonight-rule-check-sheet', 'If I Start I Have to Finish Tonight Rule Check Sheet', 'cbt'::resource_kind, 'A sheet that examines the rule that a task once started must be finished in one sitting, and what the rule does to starting.', 'Use it to help a client whose all-or-nothing rule about tasks keeps them from beginning anything.', array['Adults', 'Teens']::text[], '20 minutes', 'Many clients never start because they believe starting commits them to finishing, and finishing feels impossible. The sheet names the rule, traces where it came from, lists tasks it has blocked this month, and tests it with a deliberate half: start something, stop at a set time, and record what actually happened to the half-done task and to the client''s mood. Watch for a client who treats stopping as another failure. The alternative rule they write at the end should be one they can live with on a tired night.', '[{"id": "f0", "type": "textarea", "label": "The rule, in my words, and where I think I learned it:"}, {"id": "f1", "type": "textarea", "label": "Tasks I did not start this month because I could not finish them in one go:"}, {"id": "f2", "type": "textarea", "label": "The task I will start this week and stop on purpose at a set time:"}, {"id": "f3", "type": "textarea", "label": "What happened to the task after I stopped, and what happened to my mood:"}, {"id": "f4", "type": "textarea", "label": "What the rule has cost me, and what it was supposed to protect me from:"}, {"id": "f5", "type": "textarea", "label": "A rule I can live with on a tired night, in one sentence:"}]'::jsonb, array['ADHD', 'thinking traps', 'task initiation']::text[], '2026-11-18T15:00:00+00:00'::timestamptz),
  ('done-badly-beats-not-done-committed-action-page', 'Done Badly Beats Not Done Committed Action Page', 'act'::resource_kind, 'A committed action page for doing a stuck task deliberately below the client''s standard so that it exists at all.', 'Use it to help a client whose standards stall every task practice imperfect, finished action in service of a value.', array['Adults', 'Teens']::text[], '20 minutes, then one task', 'The page asks the client to pick a task that has sat for weeks, name the value it serves, write what a perfect version would require, and then define a bad version that would still count: the email with typos sent, the form filled in pen, the room half cleared. They do the bad version, note the mind''s protests during it, and record what the finished thing made possible. Watch for a client who does the bad version and then redoes it perfectly that night; ask what that cost. The bad version is the practice.', '[{"id": "f0", "type": "textarea", "label": "The task that has sat for weeks, and the value it actually serves:"}, {"id": "f1", "type": "textarea", "label": "What a perfect version would require, honestly:"}, {"id": "f2", "type": "textarea", "label": "The bad version that would still count, defined before I start:"}, {"id": "f3", "type": "textarea", "label": "What my mind said while I did it badly:"}, {"id": "f4", "type": "textarea", "label": "What the finished thing made possible that the perfect unfinished one did not:"}, {"id": "f5", "type": "textarea", "label": "The next task I will do badly on purpose:"}]'::jsonb, array['ADHD', 'committed action', 'perfectionism']::text[], '2026-11-18T15:00:00+00:00'::timestamptz),
  ('wise-mind-before-signing-up-for-another-thing-card', 'Wise Mind Before Signing Up for Another Thing Card', 'dbt'::resource_kind, 'A Wise Mind card for the moment of enthusiasm when a client wants to join, buy or commit to one more new thing.', 'Use it to give a client a brief pause between a burst of interest and a commitment they will be managing for months.', array['Adults', 'Teens']::text[], 'Five minutes at the moment of interest', 'Clients who light up at a new class, hobby, kit or volunteer role often have a closet full of earlier bursts. The card is used at the moment of interest: what emotion mind says, what reasonable mind says about time, money and the current list, and after a pause, what wise mind knows about this pattern and this particular pull. They set a waiting period that fits, from a day to a week, and note what the interest looks like when the wait is over. Watch for a client who uses the card to talk themselves out of everything; some pulls are worth following.', '[{"id": "f0", "type": "textarea", "label": "The new thing, and what emotion mind says about it right now:"}, {"id": "f1", "type": "textarea", "label": "What reasonable mind says about time, money and what I am already carrying:"}, {"id": "f2", "type": "textarea", "label": "After a pause: what wise mind knows about this pull and my pattern:"}, {"id": "f3", "type": "textarea", "label": "The waiting period I will give it, and when that ends:"}, {"id": "f4", "type": "textarea", "label": "At the end of the wait: how strong the interest is, and what I decided:"}, {"id": "f5", "type": "textarea", "label": "If I did sign up: what I will let go of to make room:"}]'::jsonb, array['ADHD', 'wise mind', 'decisions']::text[], '2026-11-18T15:00:00+00:00'::timestamptz),
  ('homework-start-steps-lanyard-craft', 'Homework Start Steps Lanyard Craft', 'kids'::resource_kind, 'A craft in which a child makes a lanyard of picture cards for the first five steps of starting homework, flipped one at a time.', 'Use it to turn the hardest part of homework, getting started, into a short sequence a child can see and finish.', array['Children']::text[], '30 minutes to make, used daily', 'Starting is usually the wall, not the work. The child draws five small cards for the steps that come before any homework happens: clear the spot, get the pencil, open the folder, read the first question, set the timer. The cards clip to a lanyard and the child flips each as it is done, with a small celebration at the fifth. The parent''s job is to point at the lanyard rather than talk, and to notice out loud when the five happen without help. Watch for a parent who adds a sixth card for finishing; the lanyard is about starting only.', '[{"id": "f0", "type": "textarea", "label": "Draw my five starting cards in order:"}, {"id": "f1", "type": "textarea", "label": "The small celebration I do when I flip the fifth card:"}, {"id": "f2", "type": "textarea", "label": "Where my lanyard hangs so I can find it at homework time:"}, {"id": "f3", "type": "textarea", "label": "The card that is hardest to flip, and what helps:"}, {"id": "f4", "type": "textarea", "label": "Parent: how I used pointing instead of reminding this week, and how it went:"}, {"id": "f5", "type": "textarea", "label": "Parent: a day the five steps happened with no help from me, and what I said about it:"}]'::jsonb, array['ADHD', 'children', 'craft']::text[], '2026-11-18T15:00:00+00:00'::timestamptz),
  ('substance-free-vacation-plan-sheet', 'Substance-Free Vacation Plan Sheet', 'worksheet'::resource_kind, 'A planner for a vacation without substance use covering flights, hotel minibars, dinners, free time and the people along.', 'Use it to help a client whose previous vacations ran on substance use plan a trip that is still a vacation.', array['Adults']::text[], '40 minutes before the trip', 'Vacations remove routine, add free time and often come with a culture of permission, which is why so many slips happen away from home. The sheet walks the trip hour by hour in the risky stretches: the airport bar, the arrival evening, dinners, the empty afternoon, and the companion who always orders a round. The client plans a replacement for each, who on the trip knows, how they will reach their support people from away, and what makes the trip a vacation without substances. Watch for a client who plans the first day and leaves the rest to willpower.', '[{"id": "f0", "type": "textarea", "label": "The trip, who is coming, and the moments when I used on past trips:"}, {"id": "f1", "type": "textarea", "label": "My plan for the airport, the arrival evening and the first dinner:"}, {"id": "f2", "type": "textarea", "label": "What I will do with the empty afternoon hours:"}, {"id": "f3", "type": "textarea", "label": "Who on the trip knows, and what I have asked of them:"}, {"id": "f4", "type": "textarea", "label": "How I will reach my support people from away, and when:"}, {"id": "f5", "type": "textarea", "label": "What will make this trip a real vacation for me without substances:"}, {"id": "f6", "type": "textarea", "label": "The moment I am most worried about, and my plan for the fifteen minutes around it:"}]'::jsonb, array['addiction', 'substance use', 'planning']::text[], '2026-11-18T15:00:00+00:00'::timestamptz),
  ('i-have-already-blown-it-today-thought-record', 'I Have Already Blown It Today Thought Record', 'cbt'::resource_kind, 'A thought record for the hours after a slip, catching the thought that the day is lost and more use no longer matters.', 'Use it to help a client interrupt the slide from one slip to a full return by examining the all-or-nothing thought that drives it.', array['Adults']::text[], '15 minutes, completed as soon as possible after a slip', 'The most damaging thought after a slip is usually some version of the day is ruined, so it does not matter now. The record has the client write exactly what happened, the thought, the feeling, and then test the thought: what actually changes between one use and five, what the rest of today could still hold, and what they would tell a friend in the same hour. It ends with a concrete next step for the next hour and a call to a support person. If the slip involves risk to safety, complete it in session and name 988 as a resource.', '[{"id": "f0", "type": "textarea", "label": "What happened, when, and what I was feeling just before:"}, {"id": "f1", "type": "textarea", "label": "The thought that followed, word for word:"}, {"id": "f2", "type": "textarea", "label": "The feeling now, and its strength from 0 to 100:"}, {"id": "f3", "type": "textarea", "label": "What actually changes between stopping now and continuing tonight:"}, {"id": "f4", "type": "textarea", "label": "What the rest of today could still hold:"}, {"id": "f5", "type": "textarea", "label": "What I would say to a friend who called me in this hour:"}, {"id": "f6", "type": "textarea", "label": "My next step for the next hour, and the person I will call or text, including 988 if I feel unsafe:"}]'::jsonb, array['addiction', 'substance use', 'thought record']::text[], '2026-11-18T15:00:00+00:00'::timestamptz),
  ('substance-as-a-loan-shark-metaphor-page', 'Substance as a Loan Shark Metaphor Page', 'act'::resource_kind, 'A metaphor page that treats substance use as a loan shark: fast relief now, repaid later with interest the client never agreed to.', 'Use it to help a client see the short-term relief and long-term cost of use as one transaction rather than two separate facts.', array['Adults']::text[], '20 minutes', 'The page asks the client to describe the loan honestly: what the substance lends them in the moment, relief, confidence, sleep, quiet. Then the repayment: what is collected the next day, the next week, and over years, in money, health, trust and time. They write what else could lend them the same thing at a fairer rate, and which values the shark''s visits have crowded out. Avoid moralizing; the loan is real relief, which is why it keeps getting taken. Watch for a client who minimizes the interest because it is paid later.', '[{"id": "f0", "type": "textarea", "label": "What the substance lends me in the moment, honestly:"}, {"id": "f1", "type": "textarea", "label": "What is collected the next day, and the next week:"}, {"id": "f2", "type": "textarea", "label": "What has been collected over the years, in money, health, trust and time:"}, {"id": "f3", "type": "textarea", "label": "What else could lend me the same thing at a fairer rate:"}, {"id": "f4", "type": "textarea", "label": "The values the shark''s visits have crowded out of my week:"}, {"id": "f5", "type": "textarea", "label": "What I want to say the next time the loan is offered:"}]'::jsonb, array['addiction', 'substance use', 'metaphor']::text[], '2026-11-18T15:00:00+00:00'::timestamptz),
  ('dialectical-abstinence-commitment-sheet', 'Dialectical Abstinence Commitment Sheet', 'dbt'::resource_kind, 'A sheet for holding two stances at once: full commitment to no use, and a plan for returning fast if a slip happens.', 'Use it to help a client who swings between absolute promises and giving up hold both halves without contradiction.', array['Adults']::text[], '30 minutes', 'Dialectical abstinence asks the client to commit completely to not using, as if a slip were unthinkable, while also planning in detail for what happens after one, so a slip does not become a relapse. The sheet has two halves written in that order: the commitment, in the client''s words, with what they will say to themselves when the urge argues; and the return plan, with who they call, what they do in the first hour, and how they get back to the commitment without a shame spiral. Watch for a client who writes the return plan as permission.', '[{"id": "f0", "type": "textarea", "label": "My commitment to no use, in my own words, as if a slip were not an option:"}, {"id": "f1", "type": "textarea", "label": "What I will say to myself when the urge argues that one time is fine:"}, {"id": "f2", "type": "textarea", "label": "If a slip happens: who I call in the first hour, and what I say:"}, {"id": "f3", "type": "textarea", "label": "What I do with the rest of that day so the slip stays a slip:"}, {"id": "f4", "type": "textarea", "label": "How I return to the commitment the next morning without a shame spiral:"}, {"id": "f5", "type": "textarea", "label": "How both halves can be true at once, in a sentence I believe:"}]'::jsonb, array['addiction', 'substance use', 'core DBT']::text[], '2026-11-18T15:00:00+00:00'::timestamptz),
  ('slip-disclosure-agreement-for-partners', 'Slip Disclosure Agreement for Partners', 'couples'::resource_kind, 'An agreement between partners on how a slip will be disclosed, how it will be received, and what happens in the first day after.', 'Use it to help a couple in recovery replace hiding and interrogation with a plan they both wrote while calm.', array['Couples']::text[], '40 minutes', 'Couples rarely plan for a slip, so when one happens the recovering partner hides it and the other investigates, and both feel betrayed. The sheet has the recovering partner write how and how soon they will disclose, and what they need in the first conversation; the other partner writes what they can realistically offer in that moment, what they need to feel safe, and what they will not do, such as search belongings. Then they agree on the first twenty-four hours. Watch for the agreement being written only by the partner in recovery.', '[{"id": "f0", "type": "textarea", "label": "Partner in recovery: how soon and in what words I will tell you about a slip:"}, {"id": "f1", "type": "textarea", "label": "Partner in recovery: what I need from you in the first conversation:"}, {"id": "f2", "type": "textarea", "label": "Other partner: what I can honestly offer in that moment, and what I cannot:"}, {"id": "f3", "type": "textarea", "label": "Other partner: what I need to feel steady afterward, and what I will not do:"}, {"id": "f4", "type": "textarea", "label": "Our plan for the first twenty-four hours after a disclosure:"}, {"id": "f5", "type": "textarea", "label": "How we will each get our own support, apart from each other:"}, {"id": "f6", "type": "textarea", "label": "What we will say to each other about this agreement when things are going well:"}]'::jsonb, array['addiction', 'couples', 'substance use']::text[], '2026-11-18T15:00:00+00:00'::timestamptz),
  ('game-night-temper-flare-log-sheet', 'Game Night Temper Flare Log Sheet', 'worksheet'::resource_kind, 'A log of temper flares during board games, video games or pickup sports, with the trigger, the body signs and what others saw.', 'Use it to help a client whose anger shows up in play understand what the game is really about for them.', array['Adults', 'Teens']::text[], 'Two weeks of logging', 'Anger during games is often dismissed as competitiveness, but it is the same anger in a smaller arena and it costs friendships. The client logs each flare: the game, the moment, what was at stake in their head, the first body sign, what they did and said, and what the others at the table did next. Then they look for the theme: losing, being teased, a rule dispute, being ignored. Watch for a client who stops playing rather than looking at the log; the arena is useful because the stakes are low.', '[{"id": "f0", "type": "textarea", "label": "Each flare: the game, the moment and who was there:"}, {"id": "f1", "type": "textarea", "label": "What was at stake in my head at that moment, honestly:"}, {"id": "f2", "type": "textarea", "label": "The first body sign, and how long before the outburst it arrived:"}, {"id": "f3", "type": "textarea", "label": "What I did and said, and what the others did next:"}, {"id": "f4", "type": "textarea", "label": "The theme across the flares: losing, teasing, rules, being ignored, something else:"}, {"id": "f5", "type": "textarea", "label": "What I will try at the next game night when the first body sign shows up:"}]'::jsonb, array['anger management', 'self-monitoring', 'triggers']::text[], '2026-11-18T15:00:00+00:00'::timestamptz),
  ('everyone-takes-advantage-of-me-belief-test-sheet', 'Everyone Takes Advantage of Me Belief Test Sheet', 'cbt'::resource_kind, 'A sheet that examines the belief that people routinely take advantage, tracing how it fuels anger and testing it against this week.', 'Use it to help a client whose anger runs on a sense of being used check how often it actually happens and what they do about it.', array['Adults', 'Teens']::text[], 'One week', 'A standing belief that others take advantage keeps anger primed before anything happens. The sheet has the client rate the belief, then log every interaction this week where they felt used, with the facts, their request if any, and how the other person responded when asked directly. They count the clear cases, the ambiguous ones and the ones that evaporated, and look at how often they said nothing and seethed. Watch for a client who treats never having asked as the same as having been refused.', '[{"id": "f0", "type": "textarea", "label": "The belief in my words, and how much I believe it from 0 to 100:"}, {"id": "f1", "type": "textarea", "label": "Each time this week I felt taken advantage of: who, what and the facts:"}, {"id": "f2", "type": "textarea", "label": "Whether I asked for what I wanted, and how the person responded if I did:"}, {"id": "f3", "type": "textarea", "label": "Clear cases, ambiguous cases and cases that evaporated when I looked closer:"}, {"id": "f4", "type": "textarea", "label": "How often I said nothing and stayed angry instead:"}, {"id": "f5", "type": "textarea", "label": "The belief re-rated, and one thing I will ask for directly next week:"}]'::jsonb, array['anger management', 'core beliefs', 'assertiveness']::text[], '2026-11-18T15:00:00+00:00'::timestamptz),
  ('the-argument-i-keep-winning-in-the-shower-page', 'The Argument I Keep Winning in the Shower Page', 'act'::resource_kind, 'A defusion page for the replayed argument the client keeps winning in their head, noticing what the rehearsal costs and feeds.', 'Use it to help a client who rehearses grievances see the replay as mental activity they can step back from.', array['Adults', 'Teens']::text[], '15 minutes, then daily noticing', 'Clients with anger often spend hours rehearsing the comeback they did not deliver, and the rehearsal keeps the anger warm. The page has the client write the argument they keep winning, count roughly how many times this week it played, note what it does to their body and mood, and what it has actually changed about the situation. Then they practice a name for it when it starts, such as the shower debate again, and choose where attention goes instead. Watch for a client who wants to win the real argument next; that may be a separate skill.', '[{"id": "f0", "type": "textarea", "label": "The argument I keep winning in my head, and who it is with:"}, {"id": "f1", "type": "textarea", "label": "Roughly how many times it played this week, and where I was:"}, {"id": "f2", "type": "textarea", "label": "What it does to my body and mood while it plays:"}, {"id": "f3", "type": "textarea", "label": "What all the rehearsing has changed about the real situation:"}, {"id": "f4", "type": "textarea", "label": "The name I will give it when it starts:"}, {"id": "f5", "type": "textarea", "label": "Where my attention will go when I notice it, and what I noticed when I tried:"}]'::jsonb, array['anger management', 'defusion', 'rumination']::text[], '2026-11-18T15:00:00+00:00'::timestamptz),
  ('wall-push-tipp-release-card-for-anger', 'Wall Push TIPP Release Card for Anger', 'dbt'::resource_kind, 'A TIPP card using a hard ten second wall push and a long exhale to burn off the body''s anger surge before speaking.', 'Use it to give a client a discreet intense-exercise skill for anger that works in a hallway or a bathroom.', array['Adults', 'Teens']::text[], 'One minute, when the surge hits', 'Intense exercise is one of the fastest ways to bring down the body''s arousal, and a wall push needs no space or equipment. The card has the client plant their hands on a wall, push as hard as they can for ten seconds while breathing out slowly, release, and repeat twice, then pair it with paced breathing before returning to the room. Practice it in session so it is familiar. They log the anger before and after, and what they said when they went back. Watch for a client with a shoulder or wrist issue; offer a chair press instead.', '[{"id": "f0", "type": "textarea", "label": "The situation, and my anger before the wall push from 0 to 100:"}, {"id": "f1", "type": "textarea", "label": "Three pushes of ten seconds with a slow exhale: what my body did on each:"}, {"id": "f2", "type": "textarea", "label": "My anger after, from 0 to 100:"}, {"id": "f3", "type": "textarea", "label": "What I said or did when I went back into the room:"}, {"id": "f4", "type": "textarea", "label": "Places in my week where there is always a wall and a minute:"}, {"id": "f5", "type": "textarea", "label": "What I will pair with the push next time, such as a cold drink of water:"}]'::jsonb, array['anger management', 'TIPP', 'distress tolerance']::text[], '2026-11-18T15:00:00+00:00'::timestamptz),
  ('fair-or-foul-whistle-call-game', 'Fair or Foul Whistle Call Game', 'game'::resource_kind, 'A group game in which members referee short everyday scenarios, blowing a whistle for foul or signaling fair play, then defending the call.', 'Use it to help a group separate real unfairness from the sense of unfairness anger supplies.', array['Groups', 'Teens', 'Adults']::text[], '25 minutes', 'The facilitator reads short scenarios: a coworker takes the last coffee, a friend is twenty minutes late, a sibling borrows a jacket without asking, a driver merges without signaling. Each member holds up a fair or foul card, and anyone who called foul explains what rule was broken and what a proportionate response would be. Disagreements are the point; argue them out briefly. Debrief on which calls the room split on and what that says about personal rulebooks. Watch for a member whose every call is foul; ask gently what rule they are refereeing.', '[{"id": "f0", "type": "textarea", "label": "The scenario the room split on most, and which way I called it:"}, {"id": "f1", "type": "textarea", "label": "A foul call I made, the rule I thought was broken and the proportionate response:"}, {"id": "f2", "type": "textarea", "label": "A scenario I called foul that most of the room called fair, and what I noticed:"}, {"id": "f3", "type": "textarea", "label": "A rule in my personal rulebook that other people do not seem to have:"}, {"id": "f4", "type": "textarea", "label": "One real-life foul from this week, and what a proportionate response would have been:"}]'::jsonb, array['anger management', 'game', 'fairness']::text[], '2026-11-18T15:00:00+00:00'::timestamptz),
  ('driving-back-to-check-loop-log-sheet', 'Driving Back to Check Loop Log Sheet', 'worksheet'::resource_kind, 'A log of every time the client turns the car around to check whether they hit something, locked up or left something on.', 'Use it to make the loop-back habit visible in miles and minutes before deciding together what to do about it.', array['Adults']::text[], 'Two weeks of logging', 'Looping back to check is easy to hide and expensive in time, fuel and lateness. For two weeks the client logs each loop: what the doubt said, how certain they already were before turning around, how far they drove back, what they found, and how long the relief lasted before the next doubt. Then they total the minutes and miles. The sheet does not ask them to stop yet; the record itself usually shifts the conversation. Watch for a client who checks by other means instead, such as calling someone to look.', '[{"id": "f0", "type": "textarea", "label": "Each loop: where I was headed, and what the doubt said:"}, {"id": "f1", "type": "textarea", "label": "How certain I already was before I turned around, from 0 to 100:"}, {"id": "f2", "type": "textarea", "label": "How far I drove back and how long it took:"}, {"id": "f3", "type": "textarea", "label": "What I found when I got there:"}, {"id": "f4", "type": "textarea", "label": "How long the relief lasted before the next doubt arrived:"}, {"id": "f5", "type": "textarea", "label": "Two week totals: loops, minutes, miles, and times I was late because of them:"}, {"id": "f6", "type": "textarea", "label": "Other ways I checked without driving, such as texts or cameras:"}]'::jsonb, array['OCD', 'self-monitoring', 'rituals']::text[], '2026-11-18T15:00:00+00:00'::timestamptz),
  ('responsible-for-preventing-every-harm-belief-sheet', 'Responsible for Preventing Every Harm Belief Sheet', 'cbt'::resource_kind, 'A sheet that examines the belief that the client must prevent any harm they could foresee, and the rituals that belief demands.', 'Use it to help a client see the inflated responsibility under their checking and tell it apart from ordinary care.', array['Adults', 'Teens']::text[], '25 minutes', 'Many rituals rest on a rule like if I could have prevented it and did not, it is my fault. The sheet states the rule, lists what it currently requires in a day, asks how the client would apply the same rule to a neighbor or a coworker, and uses a pie of all the people and factors that share responsibility for one feared outcome. Then they write a standard of ordinary care they would accept from anyone else. Watch for a client who agrees in session and adds the sheet to the checking at home; keep it a one-time exercise, not a ritual.', '[{"id": "f0", "type": "textarea", "label": "The responsibility rule I live by, in my own words:"}, {"id": "f1", "type": "textarea", "label": "What the rule requires of me in a typical day, listed honestly:"}, {"id": "f2", "type": "textarea", "label": "How I would apply the same rule to a neighbor or coworker, and whether I actually do:"}, {"id": "f3", "type": "textarea", "label": "One feared outcome, and everyone and everything that would share responsibility for it:"}, {"id": "f4", "type": "textarea", "label": "The standard of ordinary care I would accept from anyone else:"}, {"id": "f5", "type": "textarea", "label": "What it would mean to hold myself to that standard instead:"}]'::jsonb, array['OCD', 'core beliefs', 'responsibility']::text[], '2026-11-18T15:00:00+00:00'::timestamptz),
  ('the-certainty-store-is-closed-metaphor-page', 'The Certainty Store Is Closed Metaphor Page', 'act'::resource_kind, 'A metaphor page in which the client keeps arriving at a store that sells certainty and finds it permanently closed.', 'Use it to help a client who checks and asks for reassurance notice that the thing they are shopping for is not for sale.', array['Adults', 'Teens']::text[], '15 minutes', 'The page frames rituals and reassurance seeking as trips to a store that never opens. The client lists the trips they made today, what they hoped to buy, what they actually came home with, and how long it lasted. Then they practice the line for the next trip, the store is closed, and choose what they will do with the time instead. The metaphor is meant to be gentle and a little funny, not a lecture. Watch for a client who decides the store will open if they try a different door, meaning a new ritual.', '[{"id": "f0", "type": "textarea", "label": "The trips to the certainty store I made today, and what each cost in time:"}, {"id": "f1", "type": "textarea", "label": "What I hoped to buy on each trip:"}, {"id": "f2", "type": "textarea", "label": "What I actually came home with, and how long it lasted:"}, {"id": "f3", "type": "textarea", "label": "The line I will say at the door next time:"}, {"id": "f4", "type": "textarea", "label": "What I will do with the time instead of standing outside the store:"}, {"id": "f5", "type": "textarea", "label": "A different door I have been tempted to try, so I can see it coming:"}]'::jsonb, array['OCD', 'metaphor', 'uncertainty']::text[], '2026-11-18T15:00:00+00:00'::timestamptz),
  ('observe-the-urge-to-rearrange-without-moving-card', 'Observe the Urge to Rearrange Without Moving Card', 'dbt'::resource_kind, 'An Observe card for sitting with the urge to straighten, align or rearrange without acting, noticing the urge rise and fall.', 'Use it to give a client a mindfulness practice aimed at the not-just-right urge rather than the object.', array['Adults', 'Teens']::text[], 'Five minutes daily', 'The client sets one thing slightly off, a crooked picture, a pen out of line, and sits where they can see it for five minutes, observing the urge the way they would observe a sound: where it lives in the body, how it changes, what the mind says about it. They rate the urge each minute without moving. Afterward they note what happened to the urge and whether they fixed the object. Watch for a client who fixes it the moment the timer ends; ask them to leave it another hour. Keep the stakes small at first.', '[{"id": "f0", "type": "textarea", "label": "The thing I set slightly off, and where I sat:"}, {"id": "f1", "type": "textarea", "label": "Where the urge lives in my body, and what it feels like there:"}, {"id": "f2", "type": "textarea", "label": "The urge rated each minute from 0 to 10:"}, {"id": "f3", "type": "textarea", "label": "What my mind said during the five minutes:"}, {"id": "f4", "type": "textarea", "label": "What I did with the object when the timer ended:"}, {"id": "f5", "type": "textarea", "label": "What I noticed about the urge when I did not obey it:"}]'::jsonb, array['OCD', 'mindfulness', 'urges']::text[], '2026-11-18T15:00:00+00:00'::timestamptz),
  ('brave-refusal-to-the-redo-rule-puppet-play', 'Brave Refusal to the Redo Rule Puppet Play', 'kids'::resource_kind, 'A puppet play in which a child''s puppet practices saying no to a bossy worry that demands doing things again and again.', 'Use it to help a child rehearse refusing a redo demand in play before trying it with a real one, with the parent as ally.', array['Children']::text[], '20 minutes', 'The child picks or makes two puppets: the bossy worry that says do it again, and the brave kid. The parent voices the bossy one at first, demanding redos of silly things, retying a shoe, rewriting a letter, and the child''s puppet practices a short refusal line and does something else instead. Then they swap. Keep it funny and quick, and let the child write the refusal line. Afterward the parent and child pick one small real redo to try the line on. Watch for a parent whose bossy voice gets too real; it should be a cartoon.', '[{"id": "f0", "type": "textarea", "label": "My bossy worry puppet''s name, and the silly redos it demanded:"}, {"id": "f1", "type": "textarea", "label": "My brave puppet''s refusal line, in my words:"}, {"id": "f2", "type": "textarea", "label": "What my brave puppet did instead of the redo:"}, {"id": "f3", "type": "textarea", "label": "What it felt like when I was the bossy voice and my parent refused:"}, {"id": "f4", "type": "textarea", "label": "The one small real redo we will try the line on this week:"}, {"id": "f5", "type": "textarea", "label": "Parent: how I kept the bossy voice cartoonish, and what my child said that surprised me:"}]'::jsonb, array['OCD', 'children', 'play']::text[], '2026-11-18T15:00:00+00:00'::timestamptz),
  ('hot-shower-and-sauna-heat-sensation-log-sheet', 'Hot Shower and Sauna Heat Sensation Log Sheet', 'worksheet'::resource_kind, 'A log of flushed, hot, lightheaded sensations from a hot shower, bath or sauna, kept to practice letting them be ordinary.', 'Use it to help a client who fears heat sensations because they resemble panic meet them deliberately and record what happens.', array['Adults', 'Teens']::text[], 'Two weeks', 'Many clients with panic avoid hot showers, saunas and warm rooms because the flush and lightheadedness feel like the start of a surge. The sheet has them stay in the heat a little longer than they would like, rate the sensations and the fear separately, note what they predicted and what the sensations actually did over the following minutes, and record whether a surge followed. Agree on the starting length together and keep it modest. Watch for a client using cold water as an escape rather than a planned end.', '[{"id": "f0", "type": "textarea", "label": "Where I got hot on purpose, and how long I stayed:"}, {"id": "f1", "type": "textarea", "label": "The sensations, rated from 0 to 10, and the fear, rated separately:"}, {"id": "f2", "type": "textarea", "label": "What I predicted would happen if I stayed:"}, {"id": "f3", "type": "textarea", "label": "What the sensations actually did over the next ten minutes:"}, {"id": "f4", "type": "textarea", "label": "Whether a surge followed, and what I did either way:"}, {"id": "f5", "type": "textarea", "label": "Over two weeks: how the fear rating changed, and how long I can stay now:"}]'::jsonb, array['panic attacks', 'exposure', 'body awareness']::text[], '2026-11-18T15:00:00+00:00'::timestamptz),
  ('racing-heart-after-coffee-cause-check-sheet', 'Racing Heart After Coffee Cause Check Sheet', 'cbt'::resource_kind, 'A sheet for the fast heartbeat after coffee or an energy drink, checking the ordinary causes before the alarming ones.', 'Use it to help a client whose panic starts with a misread body sensation practice looking for the plain explanation first.', array['Adults', 'Teens']::text[], '10 minutes when it happens', 'A fast heartbeat is read by many clients as the first sign of something serious, and the fear then speeds the heart further. The sheet asks what they consumed in the last two hours, how they slept, whether they climbed stairs or rushed, what the pulse is actually doing, and what the first explanation was versus the most likely one. Then they decide what to do for the next ten minutes and note the result. Keep the tone practical, not reassuring; the client does the sorting. Watch for pulse-checking becoming its own ritual.', '[{"id": "f0", "type": "textarea", "label": "What my heart is doing right now, in plain words:"}, {"id": "f1", "type": "textarea", "label": "What I drank or ate in the last two hours, and how much:"}, {"id": "f2", "type": "textarea", "label": "How I slept, and what I was doing physically in the last ten minutes:"}, {"id": "f3", "type": "textarea", "label": "The first explanation my mind offered:"}, {"id": "f4", "type": "textarea", "label": "The most likely explanation given everything above:"}, {"id": "f5", "type": "textarea", "label": "What I will do for the next ten minutes, and what my heart did by the end of them:"}]'::jsonb, array['panic attacks', 'thinking traps', 'body awareness']::text[], '2026-11-18T15:00:00+00:00'::timestamptz),
  ('panic-veto-over-my-calendar-noticing-page', 'Panic Veto Over My Calendar Noticing Page', 'act'::resource_kind, 'A page that lists the plans panic has vetoed this month and asks what the client would do if the veto were only a vote.', 'Use it to help a client see how much of their calendar panic controls and reclaim one entry at a time.', array['Adults', 'Teens']::text[], '20 minutes', 'Panic rarely needs to show up to run a life; the fear of it is enough to cancel plans in advance. The page has the client list the invitations, errands and trips they declined or shortened this month to avoid a possible surge, what each one meant to them, and which values were overruled. Then they imagine panic as one voter rather than a veto and pick one entry to put back on the calendar with panic invited along. Watch for a client who puts back the hardest one first; smaller is better.', '[{"id": "f0", "type": "textarea", "label": "The plans I turned down or cut short this month to avoid a possible surge:"}, {"id": "f1", "type": "textarea", "label": "What each of those plans meant to me:"}, {"id": "f2", "type": "textarea", "label": "The values that were overruled when panic cast its veto:"}, {"id": "f3", "type": "textarea", "label": "What I would choose if panic had one vote instead of a veto:"}, {"id": "f4", "type": "textarea", "label": "The one entry I will put back on the calendar, with panic invited along:"}, {"id": "f5", "type": "textarea", "label": "What I will tell myself the morning of that plan:"}]'::jsonb, array['panic attacks', 'values', 'avoidance']::text[], '2026-11-18T15:00:00+00:00'::timestamptz),
  ('radical-acceptance-that-a-surge-may-come-today-card', 'Radical Acceptance That a Surge May Come Today Card', 'dbt'::resource_kind, 'A radical acceptance card for starting the day without a guarantee against panic, choosing to live the day anyway.', 'Use it to help a client whose mornings begin with bargaining against panic accept the possibility and go about their day.', array['Adults', 'Teens']::text[], 'Five minutes each morning', 'Many clients begin each day negotiating: if I can just get through today without one. The card asks them to state plainly that a surge may or may not come today, that they cannot control which, and what they will do today regardless. It includes a line for the mind''s objection and a turning-the-mind phrase for when the bargaining restarts. At night they note whether a surge came and whether the day happened anyway. Watch for acceptance being used as resignation; the day''s plan is the point.', '[{"id": "f0", "type": "textarea", "label": "Today''s plain statement: a surge may or may not come today, and I cannot choose which:"}, {"id": "f1", "type": "textarea", "label": "What I will do today either way:"}, {"id": "f2", "type": "textarea", "label": "The mind''s objection to accepting that, written out:"}, {"id": "f3", "type": "textarea", "label": "My turning-the-mind phrase for when the bargaining restarts:"}, {"id": "f4", "type": "textarea", "label": "Tonight: did a surge come, and did the day happen anyway?"}, {"id": "f5", "type": "textarea", "label": "What accepting the possibility did to the morning dread, from 0 to 10:"}]'::jsonb, array['panic attacks', 'radical acceptance', 'core DBT']::text[], '2026-11-18T15:00:00+00:00'::timestamptz),
  ('panic-in-the-car-who-drives-plan-for-partners', 'Panic in the Car Who Drives Plan for Partners', 'couples'::resource_kind, 'A plan for partners covering what happens when panic starts while one is driving: pulling over, swapping seats, words that help.', 'Use it to help a couple handle a surge on the road with a plan instead of an argument at sixty miles an hour.', array['Couples']::text[], '20 minutes', 'A surge at the wheel frightens both partners, and the passenger''s instinct to grab the wheel or talk fast often makes it worse. The sheet has the partner who gets panic write their early signs, what they want the passenger to say and not say, and whether they want to pull over or push through; the other writes what they can do calmly and what they need to feel safe in the car. Then they agree the pull-over signal and the swap routine. Practice the words once in a parked car. Watch for a plan that quietly ends with one partner never driving again.', '[{"id": "f0", "type": "textarea", "label": "Partner who gets panic: my early signs in the car, and how I will say them out loud:"}, {"id": "f1", "type": "textarea", "label": "Partner who gets panic: what I want you to say, and what I need you not to say:"}, {"id": "f2", "type": "textarea", "label": "Partner who gets panic: whether I want to pull over or keep going, and how I will tell you:"}, {"id": "f3", "type": "textarea", "label": "Other partner: what I can do calmly, and what I need to feel safe as a passenger:"}, {"id": "f4", "type": "textarea", "label": "Our pull-over signal and our seat-swap routine:"}, {"id": "f5", "type": "textarea", "label": "How we will get driving back to normal afterward, so the car does not become off limits:"}]'::jsonb, array['panic attacks', 'couples', 'planning']::text[], '2026-11-18T15:00:00+00:00'::timestamptz),
  ('morning-rush-yell-count-and-reset-sheet', 'Morning Rush Yell Count and Reset Sheet', 'worksheet'::resource_kind, 'A sheet for a parent to count the raised voices in the morning rush, find the pinch points and redesign the ten worst minutes.', 'Use it to help a parent stop treating morning yelling as a character flaw and start treating it as a schedule problem.', array['Adults']::text[], 'One week of counting, then 20 minutes', 'Most morning yelling clusters in the same two or three minutes every day, around shoes, teeth or the door. The parent tallies raised voices each morning for a week with the time and the trigger, then redesigns the worst stretch: what can be done the night before, what the child can own, what the parent will stop saying. They also pick a reset phrase for after a yell. Watch for a parent who uses the count as more evidence against themselves; the count is data about the schedule, not the person.', '[{"id": "f0", "type": "textarea", "label": "Each morning this week: how many times I raised my voice, when, and about what:"}, {"id": "f1", "type": "textarea", "label": "The two or three minutes where it happens most:"}, {"id": "f2", "type": "textarea", "label": "What could move to the night before:"}, {"id": "f3", "type": "textarea", "label": "What my child could own at their age, and how I will hand it over:"}, {"id": "f4", "type": "textarea", "label": "What I will stop saying in those minutes:"}, {"id": "f5", "type": "textarea", "label": "My reset phrase after a yell, for me and for my child:"}, {"id": "f6", "type": "textarea", "label": "After the redesign: the new count, and how the mornings feel:"}]'::jsonb, array['parenting', 'routines', 'self-monitoring']::text[], '2026-11-18T15:00:00+00:00'::timestamptz),
  ('a-good-parent-never-needs-a-break-rule-check-sheet', 'A Good Parent Never Needs a Break Rule Check Sheet', 'cbt'::resource_kind, 'A sheet that examines the rule that wanting time away from the children means something is wrong with the parent.', 'Use it to help a parent who feels guilty for needing a break test the rule and plan one without the guilt running it.', array['Adults']::text[], '20 minutes', 'The rule hides under a lot of parental exhaustion: if I were a good parent I would not want to get away. The sheet writes it out, traces where it came from, lists the evidence from parents the client admires, asks what the rule costs the children when the parent never refuels, and rewrites it. Then the parent plans one break this week and notes the guilt before, during and after. Watch for a parent who takes the break and spends all of it feeling bad about it; that is the rule working from a distance.', '[{"id": "f0", "type": "textarea", "label": "The rule, in my words, and whose voice it sounds like:"}, {"id": "f1", "type": "textarea", "label": "Parents I admire who take breaks, and what I think of them for it:"}, {"id": "f2", "type": "textarea", "label": "What the rule costs my children when I never refuel:"}, {"id": "f3", "type": "textarea", "label": "The rule rewritten in a way I could say to another parent:"}, {"id": "f4", "type": "textarea", "label": "The break I will take this week: when, how long, and who has the kids:"}, {"id": "f5", "type": "textarea", "label": "Guilt before, during and after the break, from 0 to 100, and what I noticed:"}]'::jsonb, array['parenting', 'core beliefs', 'self-care']::text[], '2026-11-18T15:00:00+00:00'::timestamptz),
  ('checkout-candy-aisle-values-page-for-parents', 'Checkout Candy Aisle Values Page for Parents', 'act'::resource_kind, 'A values page for the checkout standoff: what the parent wants to stand for when a child melts down over candy in public.', 'Use it to help a parent decide in advance who they want to be in the aisle, so the audience does not decide for them.', array['Adults']::text[], '15 minutes before the next shop', 'The candy aisle combines a tired child, an audience and a parent''s own hunger to be seen as competent. The page asks the parent to describe the usual standoff, the thoughts about onlookers, what they typically do and why, and then what they would want to stand for if nobody were watching. They write their line for the child and their line for themselves, and choose one thing to do with the discomfort of being watched. Watch for a parent whose plan is to avoid stores with children altogether.', '[{"id": "f0", "type": "textarea", "label": "The usual standoff: what my child does, what I think, what I do:"}, {"id": "f1", "type": "textarea", "label": "The thoughts about onlookers that show up, word for word:"}, {"id": "f2", "type": "textarea", "label": "What I would want to stand for in that aisle if nobody were watching:"}, {"id": "f3", "type": "textarea", "label": "My line for my child, short enough to say twice:"}, {"id": "f4", "type": "textarea", "label": "My line for myself while the meltdown runs its course:"}, {"id": "f5", "type": "textarea", "label": "What I will do with the discomfort of being watched:"}, {"id": "f6", "type": "textarea", "label": "After the next shop: what I did, and how close it was to what I wrote:"}]'::jsonb, array['parenting', 'values', 'willingness']::text[], '2026-11-18T15:00:00+00:00'::timestamptz),
  ('self-soothe-five-minutes-after-bedtime-card-for-parents', 'Self-Soothe Five Minutes After Bedtime Card for Parents', 'dbt'::resource_kind, 'A self-soothe card for the first five minutes after the children are down, before chores, screens or the day''s review take over.', 'Use it to give a worn-out parent one small sensory reset between the parenting day and the rest of the evening.', array['Adults']::text[], 'Five minutes nightly', 'The minutes after bedtime usually go straight to dishes or a phone, and the parent arrives at their own bedtime having never stopped. The card asks for a five minute self-soothe using one sense: a warm drink held with both hands, a particular song, a window opened to the night air, a lotion with a scent they like. They choose it in advance, do it before anything else, and note mood before and after. Watch for a parent who turns it into another task to fail; if five minutes is too many, make it two.', '[{"id": "f0", "type": "textarea", "label": "The sense I will use, and the exact thing I will do with it:"}, {"id": "f1", "type": "textarea", "label": "Where in the house it happens, and what I will put down first:"}, {"id": "f2", "type": "textarea", "label": "Each night: did I do it before anything else?"}, {"id": "f3", "type": "textarea", "label": "Mood before and after, from 0 to 10:"}, {"id": "f4", "type": "textarea", "label": "What pulled me away on the nights I skipped it:"}, {"id": "f5", "type": "textarea", "label": "What the rest of the evening was like on the nights I did it:"}]'::jsonb, array['parenting', 'self-soothing', 'self-care']::text[], '2026-11-18T15:00:00+00:00'::timestamptz),
  ('family-vote-paddles-craft', 'Family Vote Paddles Craft', 'kids'::resource_kind, 'A craft in which a child makes yes, no and maybe paddles for the family to vote on small decisions at dinner or on weekends.', 'Use it to give a child a real voice in small family choices and a parent a way to say no that is not the only no in the room.', array['Children']::text[], '30 minutes to make, used at family meetings', 'The child decorates three paddles, green for yes, red for no, yellow for maybe or tell me more, for each family member. The parent then holds short votes on things that can genuinely be decided by vote: the movie, the park, the pancake shape. Everyone votes at once, and a yellow paddle means that person gets to ask one question before the revote. The parent explains which decisions are grown-up decisions and are not up for a vote, so the paddles stay trustworthy. Watch for votes that are rigged, which children notice fast.', '[{"id": "f0", "type": "textarea", "label": "Draw my three paddles and the colors I picked:"}, {"id": "f1", "type": "textarea", "label": "Three things our family will vote on with the paddles:"}, {"id": "f2", "type": "textarea", "label": "The grown-up decisions that are not for voting, so everyone knows:"}, {"id": "f3", "type": "textarea", "label": "The first vote we held, and how it came out:"}, {"id": "f4", "type": "textarea", "label": "A time I held up yellow, and the question I asked:"}, {"id": "f5", "type": "textarea", "label": "Parent: how it felt to be outvoted, and what I said about it:"}]'::jsonb, array['parenting', 'children', 'craft']::text[], '2026-11-18T15:00:00+00:00'::timestamptz),
  ('visitor-schedule-and-rest-windows-sheet-for-new-parents', 'Visitor Schedule and Rest Windows Sheet for New Parents', 'worksheet'::resource_kind, 'A sheet for new parents to decide who visits when, how long they stay, what they bring and which hours are closed to everyone.', 'Use it to help a new parent protect rest and feeding without feeling they are turning family away.', array['Adults']::text[], '20 minutes', 'The first weeks fill with visitors who mean well and stay long, and the new parent ends up hosting through exhaustion. The sheet asks for the visitor list in order of who actually helps, the hours that are closed to everyone, a visit length that is spoken out loud in the invitation, and one job each visitor can do, such as bringing a meal or holding the baby while the parent showers. It also offers the words for ending a visit. Watch for a parent who cannot write a closed hour because every hour belongs to someone else.', '[{"id": "f0", "type": "textarea", "label": "Who wants to visit, and who actually helps when they are here:"}, {"id": "f1", "type": "textarea", "label": "The hours that are closed to everyone, no exceptions:"}, {"id": "f2", "type": "textarea", "label": "The visit length I will state in the invitation, in exact words:"}, {"id": "f3", "type": "textarea", "label": "One job each visitor can do while they are here:"}, {"id": "f4", "type": "textarea", "label": "The words I will use to end a visit that has run long:"}, {"id": "f5", "type": "textarea", "label": "Who will be the gatekeeper when I cannot say it myself:"}]'::jsonb, array['perinatal and postpartum', 'boundaries', 'planning']::text[], '2026-11-18T15:00:00+00:00'::timestamptz),
  ('no-rush-of-love-yet-thought-check-sheet', 'No Rush of Love Yet Thought Check Sheet', 'cbt'::resource_kind, 'A thought check for a new parent who did not feel the promised rush of love and concludes something is wrong with them or the bond.', 'Use it to help a new parent separate the story they were told about bonding from what connection actually looks like day by day.', array['Adults']::text[], '20 minutes', 'The absence of an instant rush is common and rarely talked about, so the parent who does not feel it believes they are the exception. The sheet captures the expectation, where it came from, the thought now, the evidence of care and attention in the last day regardless of feeling, what other parents have quietly said when asked, and a fairer account of how connection grows. Watch for persistent flatness or thoughts of harm; if present, complete the sheet in session, follow up closely and name 988 as a resource for a crisis.', '[{"id": "f0", "type": "textarea", "label": "What I expected to feel, and where that expectation came from:"}, {"id": "f1", "type": "textarea", "label": "What I actually feel, and the thought I have about it:"}, {"id": "f2", "type": "textarea", "label": "The care and attention I gave the baby in the last day, regardless of feeling:"}, {"id": "f3", "type": "textarea", "label": "What other parents have told me when I asked honestly:"}, {"id": "f4", "type": "textarea", "label": "A fairer account of how connection tends to grow:"}, {"id": "f5", "type": "textarea", "label": "What I will do this week to let it grow, and who I will tell how I am feeling, including 988 if I ever feel unsafe:"}]'::jsonb, array['perinatal and postpartum', 'thinking traps', 'connection']::text[], '2026-11-18T15:00:00+00:00'::timestamptz),
  ('the-baby-books-say-mind-noise-defusion-page', 'The Baby Books Say Mind Noise Defusion Page', 'act'::resource_kind, 'A defusion page for the chorus of advice from books, apps and relatives, noticing it as noise rather than instruction.', 'Use it to help a new parent hear the advice chorus as mind chatter and find their own judgment underneath it.', array['Adults']::text[], '15 minutes', 'New parents often cannot hear themselves over the advice, and every choice arrives with a contradicting rule attached. The page asks the parent to write the loudest lines from the chorus, where each came from, what the chorus sounds like at three in the morning, and what their own judgment says when the chorus is turned down for a minute. They choose one decision to make by their own judgment this week and note how it went. Watch for a parent who swaps one chorus for another, including the clinician''s.', '[{"id": "f0", "type": "textarea", "label": "The loudest lines from the chorus this week, and where each came from:"}, {"id": "f1", "type": "textarea", "label": "What the chorus sounds like at three in the morning:"}, {"id": "f2", "type": "textarea", "label": "A name for the chorus so I can notice it, such as the baby books again:"}, {"id": "f3", "type": "textarea", "label": "What my own judgment says when the chorus is turned down for a minute:"}, {"id": "f4", "type": "textarea", "label": "The one decision I will make by my own judgment this week:"}, {"id": "f5", "type": "textarea", "label": "How that decision went, and what the chorus said afterward:"}]'::jsonb, array['perinatal and postpartum', 'defusion', 'values']::text[], '2026-11-18T15:00:00+00:00'::timestamptz),
  ('opposite-action-to-hiding-the-hard-days-from-friends-card', 'Opposite Action to Hiding the Hard Days From Friends Card', 'dbt'::resource_kind, 'An opposite action card for the shame-driven urge to tell friends everything is wonderful when the days are hard.', 'Use it to help a new parent act against the pull to hide and let one person see the real week.', array['Adults']::text[], '15 minutes, then one conversation', 'Shame''s urge is to hide, and new parents hide behind photos and fine. The card has the parent name the urge, check whether the shame fits the facts, meaning whether a hard week is actually something to be ashamed of, and plan the opposite: telling one trusted person one true thing about the week, in person or by voice rather than text. They note the friend''s response and the shame before and after. Watch for a parent who picks the one friend most likely to judge; the first try should be with someone safe.', '[{"id": "f0", "type": "textarea", "label": "The version of the week I have been telling people, and the real version:"}, {"id": "f1", "type": "textarea", "label": "Does the shame fit the facts? Is a hard week something to be ashamed of?"}, {"id": "f2", "type": "textarea", "label": "The one person I will tell one true thing, and how I will say it:"}, {"id": "f3", "type": "textarea", "label": "What I will do with my body and voice so the telling goes all the way:"}, {"id": "f4", "type": "textarea", "label": "How they responded:"}, {"id": "f5", "type": "textarea", "label": "Shame before and after, from 0 to 100, and what I noticed:"}]'::jsonb, array['perinatal and postpartum', 'opposite action', 'support']::text[], '2026-11-18T15:00:00+00:00'::timestamptz),
  ('morning-shower-turn-plan-for-new-parents', 'Morning Shower Turn Plan for New Parents', 'couples'::resource_kind, 'A small logistics plan for new parents on who showers first, who has the baby, and how both get ten clean minutes each morning.', 'Use it to help a couple settle the tiny daily fairness fights that stand in for bigger ones in the newborn weeks.', array['Couples']::text[], '15 minutes', 'The shower is one of the first things a new parent loses and one of the first things couples fight about, usually by proxy. The sheet has each partner say what the morning looks like for them, what they need to feel like a person by nine, and which days are tighter. Then they agree a rotation or a rule, what the partner with the baby does during the shower, and what happens when the plan breaks. Watch for the partner who always goes second and never gets a turn; the rotation should be written, not remembered.', '[{"id": "f0", "type": "textarea", "label": "Partner A: what my morning actually looks like right now, and what I need to feel like a person:"}, {"id": "f1", "type": "textarea", "label": "Partner B: what my morning actually looks like right now, and what I need to feel like a person:"}, {"id": "f2", "type": "textarea", "label": "The days that are tighter for each of us:"}, {"id": "f3", "type": "textarea", "label": "Our rotation or rule for who showers first:"}, {"id": "f4", "type": "textarea", "label": "What the partner with the baby does during the shower, and the signal if they need help:"}, {"id": "f5", "type": "textarea", "label": "What happens when the plan breaks, so it is not a fight:"}, {"id": "f6", "type": "textarea", "label": "After two weeks: whether both of us are actually getting our ten minutes:"}]'::jsonb, array['perinatal and postpartum', 'couples', 'fairness']::text[], '2026-11-18T15:00:00+00:00'::timestamptz),
  ('comparison-trigger-accounts-mute-list-sheet', 'Comparison Trigger Accounts Mute List Sheet', 'worksheet'::resource_kind, 'A sheet for identifying the accounts, feeds and group chats that reliably leave the client feeling smaller, and deciding what to mute.', 'Use it to help a client reduce the daily comparison diet instead of arguing with every comparison it produces.', array['Adults', 'Teens']::text[], 'One week of noticing, then 20 minutes', 'Clients can spend a whole session disputing one comparison while the feed supplies fifty more a day. The sheet has them note for a week which accounts, group chats and feeds they feel worse after, what the specific comparison was, and how long the feeling lasted. Then they sort into mute, unfollow, limit and keep, and do the muting in session. They also add one account or contact that reliably leaves them feeling more like themselves. Watch for a client who cannot mute a friend out of guilt; muting is invisible.', '[{"id": "f0", "type": "textarea", "label": "Each time this week I felt smaller after looking at something: what it was:"}, {"id": "f1", "type": "textarea", "label": "The specific comparison each time, in one line:"}, {"id": "f2", "type": "textarea", "label": "How long the feeling lasted, and what I did with it:"}, {"id": "f3", "type": "textarea", "label": "Mute, unfollow, limit or keep, for each one:"}, {"id": "f4", "type": "textarea", "label": "What I muted or limited today, in session:"}, {"id": "f5", "type": "textarea", "label": "One account or person I will add or see more of because I feel like myself afterward:"}]'::jsonb, array['self-esteem', 'self-monitoring', 'boundaries']::text[], '2026-11-18T15:00:00+00:00'::timestamptz),
  ('my-opinion-does-not-count-in-the-room-belief-test-sheet', 'My Opinion Does Not Count in the Room Belief Test Sheet', 'cbt'::resource_kind, 'A sheet that tests the belief that the client''s view carries no weight by having them voice one opinion and track what happens.', 'Use it to help a client who stays silent in meetings and groups gather real evidence about how their views land.', array['Adults', 'Teens']::text[], 'One week', 'The belief is self-sealing: the client never speaks, so their opinion is never heard, so the belief is confirmed. The sheet has them rate the belief, choose two low-stakes settings this week to offer one opinion in a plain sentence, predict the reaction, and record the actual response, including whether the idea was used, built on or ignored. Ignored is useful data too; ask how often other people''s opinions are ignored in the same room. Watch for a client who hedges the opinion into nothing before saying it.', '[{"id": "f0", "type": "textarea", "label": "The belief, and how much I believe it from 0 to 100:"}, {"id": "f1", "type": "textarea", "label": "The two settings this week where I will offer one opinion in a plain sentence:"}, {"id": "f2", "type": "textarea", "label": "My prediction of what will happen each time:"}, {"id": "f3", "type": "textarea", "label": "What I actually said, without hedges:"}, {"id": "f4", "type": "textarea", "label": "What happened: used, built on, discussed, ignored, something else:"}, {"id": "f5", "type": "textarea", "label": "How often other people''s opinions get ignored in the same room:"}, {"id": "f6", "type": "textarea", "label": "The belief re-rated, and what I want to say next week:"}]'::jsonb, array['self-esteem', 'behavioral experiment', 'assertiveness']::text[], '2026-11-18T15:00:00+00:00'::timestamptz),
  ('switching-off-the-self-esteem-scoreboard-page', 'Switching Off the Self-Esteem Scoreboard Page', 'act'::resource_kind, 'A page that notices the running scoreboard the mind keeps on the client''s worth and practices acting without checking the score.', 'Use it to help a client step out of the rating game rather than trying to win it.', array['Adults', 'Teens']::text[], '20 minutes, then daily noticing', 'Clients often come wanting a higher score, and the page suggests the scoreboard itself is the problem. They list the events that moved their score today, up and down, notice how often they checked it, and what checking cost in attention. Then they choose one valued activity and do it with the scoreboard deliberately unwatched, returning attention to the activity each time the mind reports a score. Watch for a client who tries to feel good about the score instead of leaving it; that is still playing.', '[{"id": "f0", "type": "textarea", "label": "What moved my score up today, and what moved it down:"}, {"id": "f1", "type": "textarea", "label": "Roughly how many times I checked the scoreboard, and what checking cost:"}, {"id": "f2", "type": "textarea", "label": "The valued activity I will do without watching the score:"}, {"id": "f3", "type": "textarea", "label": "The words I will use when the mind reports a score mid-activity:"}, {"id": "f4", "type": "textarea", "label": "What the activity was like with the board unwatched:"}, {"id": "f5", "type": "textarea", "label": "What I notice about the score when I have not looked at it for a while:"}]'::jsonb, array['self-esteem', 'defusion', 'self-as-context']::text[], '2026-11-18T15:00:00+00:00'::timestamptz),
  ('self-validation-before-checking-likes-card', 'Self-Validation Before Checking Likes Card', 'dbt'::resource_kind, 'A self-validation card for the moment before checking how a post, message or piece of work was received by others.', 'Use it to help a client whose sense of worth waits on other people''s reactions offer themselves the first response.', array['Adults', 'Teens']::text[], 'Two minutes before checking', 'The reflex to check who liked it is a request for validation that the client could meet first. The card has them pause before opening the app or inbox, write what they did and why it mattered to them, what they would say to a friend who did the same, and one sentence of validation in their own words. Then they check, and note what the external response did to the feeling they had just given themselves. Watch for self-validation delivered sarcastically; have the client read it aloud in session.', '[{"id": "f0", "type": "textarea", "label": "What I posted, sent or made, and why it mattered to me:"}, {"id": "f1", "type": "textarea", "label": "What I would say to a friend who had just done the same thing:"}, {"id": "f2", "type": "textarea", "label": "One sentence of validation for myself, in my own words:"}, {"id": "f3", "type": "textarea", "label": "The feeling after my own sentence, from 0 to 10:"}, {"id": "f4", "type": "textarea", "label": "What the external response was, and what it did to that feeling:"}, {"id": "f5", "type": "textarea", "label": "Which response I want to be the one that counts, and how I will practice that:"}]'::jsonb, array['self-esteem', 'validation', 'core DBT']::text[], '2026-11-18T15:00:00+00:00'::timestamptz),
  ('guess-my-proud-moment-card-draw-game', 'Guess My Proud Moment Card Draw Game', 'game'::resource_kind, 'A group game in which anonymous proud moments are drawn from a hat and the group guesses whose each one is before the owner claims it.', 'Use it to let members say something good about themselves without having to say it first.', array['Groups', 'Teens', 'Adults']::text[], '25 minutes', 'Each member writes one thing they are quietly proud of from the last year on a slip, no names. Slips go in a hat, are drawn and read aloud, and the group guesses the owner with reasons; the owner then claims it and says one sentence about why it mattered. Members who guessed wrong say what the moment made them think of in themselves. Debrief on how it felt to hear your moment read in someone else''s voice, and on the moments nobody guessed. Watch for a member who writes something self-deprecating; invite a second slip.', '[{"id": "f0", "type": "textarea", "label": "The proud moment I wrote, and how it felt to see it drawn:"}, {"id": "f1", "type": "textarea", "label": "Who the group guessed, and what the wrong guesses noticed about me:"}, {"id": "f2", "type": "textarea", "label": "A moment I guessed wrong, and what it made me think of in myself:"}, {"id": "f3", "type": "textarea", "label": "The moment in the room I would have been proud of too:"}, {"id": "f4", "type": "textarea", "label": "Something I did not write down because it felt too small, that I will claim now:"}]'::jsonb, array['self-esteem', 'game', 'strengths']::text[], '2026-11-18T15:00:00+00:00'::timestamptz),
  ('group-fitness-class-back-row-to-front-row-steps-sheet', 'Group Fitness Class Back Row to Front Row Steps Sheet', 'worksheet'::resource_kind, 'A step plan for a client who hides in the back of a class, or skips it, to move toward being seen while moving.', 'Use it to turn a group class the client already wants to attend into a graded practice in being watched.', array['Adults', 'Teens']::text[], 'Four to six weeks', 'Group classes, from yoga to a run club, are a ready-made ladder for a client whose fear is being watched doing something imperfectly. The sheet has them write the current step, arriving late and leaving early from the back corner perhaps, and plan the next ones: arriving on time, a middle row, asking the instructor one question, a front spot, a mistake left uncorrected. For each step they predict attention from others and record what they noticed. Watch for a client who scales the ladder in one week; slower sticks.', '[{"id": "f0", "type": "textarea", "label": "Where I stand now in the class, and what I do to stay unnoticed:"}, {"id": "f1", "type": "textarea", "label": "The steps from here to the front row, in the order I will take them:"}, {"id": "f2", "type": "textarea", "label": "For this week''s step: how much attention I predict from others, from 0 to 100:"}, {"id": "f3", "type": "textarea", "label": "What I actually noticed other people doing while I took the step:"}, {"id": "f4", "type": "textarea", "label": "The thought that showed up mid-class, and what I did with it:"}, {"id": "f5", "type": "textarea", "label": "The step for next week, and what would make it a little harder:"}]'::jsonb, array['social anxiety', 'exposure', 'hierarchy']::text[], '2026-11-18T15:00:00+00:00'::timestamptz),
  ('i-talked-too-much-conversation-share-check-sheet', 'I Talked Too Much Conversation Share Check Sheet', 'cbt'::resource_kind, 'A sheet for the replay after a social event in which the client is sure they dominated, checking the replay against what can be known.', 'Use it to help a client whose evenings end in a critical replay examine its accuracy and set it down.', array['Adults', 'Teens']::text[], '15 minutes the next morning', 'The post-event replay runs in the critic''s voice and edits out everything but the client''s own talking. The sheet has them write the replay''s verdict, estimate how much of the conversation they held, list what others said and asked, note any signs of boredom they actually saw rather than feared, and consider what they would conclude about a friend who talked the same amount. It ends with a time limit on the replay for next time. Watch for a client who then swings to saying nothing at the next event.', '[{"id": "f0", "type": "textarea", "label": "The replay''s verdict, in its exact words:"}, {"id": "f1", "type": "textarea", "label": "My estimate of how much of the conversation I held, as a fraction:"}, {"id": "f2", "type": "textarea", "label": "What the other people said and asked, as much as I can remember:"}, {"id": "f3", "type": "textarea", "label": "Signs of boredom I actually saw, versus signs I feared:"}, {"id": "f4", "type": "textarea", "label": "What I would conclude about a friend who talked the same amount:"}, {"id": "f5", "type": "textarea", "label": "The time limit I will put on the replay after the next event, and what I will do when it expires:"}]'::jsonb, array['social anxiety', 'rumination', 'thinking traps']::text[], '2026-11-18T15:00:00+00:00'::timestamptz),
  ('returning-the-shoes-at-the-counter-willingness-page', 'Returning the Shoes at the Counter Willingness Page', 'act'::resource_kind, 'A willingness page for a small dreaded interaction, a return at a store counter, done with the discomfort carried along.', 'Use it to give a client one concrete errand to practice acting with social discomfort rather than waiting for it to pass.', array['Adults', 'Teens']::text[], 'One errand, then 10 minutes', 'A return at a counter has everything the client avoids: being looked at, possibly questioned, holding up a line. The page has them write the errand, the discomfort they expect and where it will sit in the body, the value the errand serves, even if it is only their own money back, and a willingness rating. Then they do it and record what the discomfort did while they stood there, and what the clerk actually did. Watch for a client who sends someone else, or waits until the return window closes.', '[{"id": "f0", "type": "textarea", "label": "The return I have been putting off, and how long it has sat:"}, {"id": "f1", "type": "textarea", "label": "The discomfort I expect, and where in the body it will sit:"}, {"id": "f2", "type": "textarea", "label": "What doing it serves: my money back, my word to myself, something else:"}, {"id": "f3", "type": "textarea", "label": "My willingness to carry the discomfort to the counter, from 0 to 10:"}, {"id": "f4", "type": "textarea", "label": "What the discomfort did while I stood at the counter:"}, {"id": "f5", "type": "textarea", "label": "What the clerk actually did and said:"}, {"id": "f6", "type": "textarea", "label": "The next small dreaded errand I will carry discomfort to:"}]'::jsonb, array['social anxiety', 'willingness', 'committed action']::text[], '2026-11-18T15:00:00+00:00'::timestamptz),
  ('give-skill-in-the-elevator-small-talk-card', 'GIVE Skill in the Elevator Small Talk Card', 'dbt'::resource_kind, 'A GIVE card for the thirty seconds of elevator or hallway small talk with a coworker or neighbor.', 'Use it to give a client a short script for the micro-interactions they currently survive by staring at the floor.', array['Adults', 'Teens']::text[], 'A few seconds, several times a week', 'GIVE stands for being Gentle, acting Interested, Validating and using an Easy manner, and an elevator ride is just long enough for all four. The card has the client plan one gentle opener, one interested question, one validating response to whatever comes back, and the easy manner they will aim for, such as a half smile. They try it twice this week and note what the other person did. Debrief in session on what the thirty seconds were like compared to the floor-staring version. Watch for a client who rehearses so hard they miss the reply.', '[{"id": "f0", "type": "textarea", "label": "My gentle opener, in a sentence I would actually say:"}, {"id": "f1", "type": "textarea", "label": "My interested question if they reply:"}, {"id": "f2", "type": "textarea", "label": "How I will validate whatever they say back:"}, {"id": "f3", "type": "textarea", "label": "The easy manner I am aiming for, in my face and shoulders:"}, {"id": "f4", "type": "textarea", "label": "Two tries this week: who it was, and what they did:"}, {"id": "f5", "type": "textarea", "label": "What the thirty seconds were like compared to looking at the floor:"}]'::jsonb, array['social anxiety', 'GIVE', 'interpersonal effectiveness']::text[], '2026-11-18T15:00:00+00:00'::timestamptz),
  ('follow-up-question-volley-game', 'Follow-Up Question Volley Game', 'game'::resource_kind, 'A pairs game in which partners keep a conversation going using only follow-up questions, counting how long the volley lasts.', 'Use it to show a socially anxious client that keeping a conversation alive takes curiosity, not cleverness.', array['Groups', 'Teens', 'Adults']::text[], '20 minutes', 'Pairs start with one person''s answer to a posted question, such as what did you do last weekend. The listener may only respond with a follow-up question about what was just said; no statements, no changing the subject. Count the volley until someone breaks the rule or runs dry, then swap. Play three rounds and see whether the volleys get longer. Debrief on which questions opened things up, how it felt to be asked, and how little the questioner had to be interesting. Watch for a pair interrogating rather than following.', '[{"id": "f0", "type": "textarea", "label": "Our longest volley, and the question that kept it alive:"}, {"id": "f1", "type": "textarea", "label": "The moment we ran dry, and what I could have asked:"}, {"id": "f2", "type": "textarea", "label": "What it felt like to be asked follow-up questions about something ordinary:"}, {"id": "f3", "type": "textarea", "label": "How much I had to be interesting as the questioner:"}, {"id": "f4", "type": "textarea", "label": "One follow-up question I will use in a real conversation this week:"}]'::jsonb, array['social anxiety', 'game', 'social skills']::text[], '2026-11-18T15:00:00+00:00'::timestamptz),
  ('mail-still-arriving-in-their-name-steps-sheet', 'Mail Still Arriving in Their Name Steps Sheet', 'worksheet'::resource_kind, 'A sheet for the small ambushes of mail, calls and renewal notices in the name of someone who has died, with steps and a pace.', 'Use it to help a grieving client handle the administrative reminders at a pace that does not reopen the day each time.', array['Adults']::text[], '20 minutes, then as mail arrives', 'Months after a death, catalogs, appointment reminders and renewal notices keep arriving, and each one is a small ambush. The sheet has the client list what still comes, mark which can be stopped with a single call, which need paperwork and which they want to keep receiving, and set a day of the week for the calls so they are not made in the raw moment of opening the envelope. It also asks what they will do with the first minute after an ambush. Watch for a client who keeps everything unopened in a pile; offer to open one together.', '[{"id": "f0", "type": "textarea", "label": "What still arrives in their name: mail, calls, emails, reminders:"}, {"id": "f1", "type": "textarea", "label": "Which ones one phone call can stop, and the number to call:"}, {"id": "f2", "type": "textarea", "label": "Which ones need paperwork, and what I need to find first:"}, {"id": "f3", "type": "textarea", "label": "Which ones I want to keep receiving, and why:"}, {"id": "f4", "type": "textarea", "label": "The day of the week I will make the calls, not the day the mail comes:"}, {"id": "f5", "type": "textarea", "label": "What I will do with the first minute after an ambush:"}]'::jsonb, array['grief and loss', 'pacing', 'planning']::text[], '2026-11-18T15:00:00+00:00'::timestamptz),
  ('they-would-be-disappointed-in-how-i-am-coping-check-sheet', 'They Would Be Disappointed in How I Am Coping Check Sheet', 'cbt'::resource_kind, 'A thought check for the grieving client who imagines the person they lost judging how they are getting through it.', 'Use it to help a client examine an imagined verdict from the person they lost against what that person was actually like.', array['Adults', 'Teens']::text[], '20 minutes', 'Grief often borrows the voice of the person who died and uses it for self-criticism. The sheet captures the imagined verdict, the feeling it brings, what the person actually said to the client in hard times while alive, how they treated others who were struggling, and what they would most likely say if they could see this week. Then the client writes the sentence in that person''s real voice. Watch for a client whose relationship with the person was genuinely critical; then the work is about whose voice gets the final word.', '[{"id": "f0", "type": "textarea", "label": "The verdict I imagine them delivering about how I am coping:"}, {"id": "f1", "type": "textarea", "label": "The feeling it brings, and its strength from 0 to 100:"}, {"id": "f2", "type": "textarea", "label": "What they actually said to me in hard times when they were alive:"}, {"id": "f3", "type": "textarea", "label": "How they treated other people who were struggling:"}, {"id": "f4", "type": "textarea", "label": "What they would most likely say if they could see this week:"}, {"id": "f5", "type": "textarea", "label": "That sentence written in their real voice, as I remember it:"}]'::jsonb, array['grief and loss', 'thinking traps', 'self-criticism']::text[], '2026-11-18T15:00:00+00:00'::timestamptz),
  ('both-grateful-and-gutted-both-and-page', 'Both Grateful and Gutted Both-And Page', 'act'::resource_kind, 'A page for holding gratitude for what was and grief for what is gone at the same time, without one canceling the other.', 'Use it to help a client who feels they must choose between being thankful and being devastated make room for both.', array['Adults', 'Teens']::text[], '20 minutes', 'Well-meaning people tell the grieving to be grateful for the time they had, and the client hears it as an instruction to stop hurting. The page has two columns written side by side: what I am grateful for about them and us, and what I am gutted to have lost. Then the client writes sentences that join the columns with and rather than but, and notices what happens in the body when both are allowed. Watch for a client who fills one column and leaves the other blank; ask which column feels forbidden.', '[{"id": "f0", "type": "textarea", "label": "What I am grateful for about them and about what we had:"}, {"id": "f1", "type": "textarea", "label": "What I am gutted to have lost, in plain words:"}, {"id": "f2", "type": "textarea", "label": "Three sentences that hold one from each column, joined with and:"}, {"id": "f3", "type": "textarea", "label": "Which column felt harder to fill, and why:"}, {"id": "f4", "type": "textarea", "label": "What happened in my body when both were allowed on the same page:"}, {"id": "f5", "type": "textarea", "label": "A line I can say to the people who tell me to be grateful:"}]'::jsonb, array['grief and loss', 'acceptance', 'core ACT']::text[], '2026-11-18T15:00:00+00:00'::timestamptz),
  ('observe-their-handwriting-without-the-story-card', 'Observe Their Handwriting Without the Story Card', 'dbt'::resource_kind, 'An Observe card for sitting with a note, list or card in the handwriting of someone who has died, noticing without narrating.', 'Use it to give a grieving client a way to be with an object that matters without being swept away by it every time.', array['Adults', 'Teens']::text[], 'Five minutes', 'A grocery list or a birthday card in their handwriting can undo a client in seconds, so many hide these away. The card has the client hold one item for five minutes and observe it as an object: the slant of the letters, the color of the ink, the paper, where the pen pressed hard. When the story starts, they note it and return to the ink. Afterward they record what the five minutes were like and whether they want to see the object more often or less. Watch for a client who needs this done in session first; many do.', '[{"id": "f0", "type": "textarea", "label": "The item I chose, and where it has been kept:"}, {"id": "f1", "type": "textarea", "label": "What I observed: the letters, the ink, the paper, the pressure of the pen:"}, {"id": "f2", "type": "textarea", "label": "The moments the story started, and what brought me back to the ink:"}, {"id": "f3", "type": "textarea", "label": "What the five minutes were like, from start to finish:"}, {"id": "f4", "type": "textarea", "label": "Whether I want this object closer or further away for now:"}, {"id": "f5", "type": "textarea", "label": "When I will do this again, and whether I want company:"}]'::jsonb, array['grief and loss', 'mindfulness', 'core DBT']::text[], '2026-11-18T15:00:00+00:00'::timestamptz),
  ('handprint-heart-keepsake-craft', 'Handprint Heart Keepsake Craft', 'kids'::resource_kind, 'A craft in which a child paints their handprint and a parent''s into a heart shape in memory of someone who has died, with a line each.', 'Use it to give a grieving child something to make with their hands and a parent a way to talk about the person while making it.', array['Children']::text[], '30 minutes', 'The child and parent each paint one hand and press them together on card so the thumbs form a heart, then decorate around it. While it dries the parent asks what the child remembers about the person, shares one memory of their own, and the child chooses one line to write or dictate inside the heart. Keep the questions open and let silence happen. The keepsake can hang somewhere the child chooses. Watch for a parent who hides their own sadness entirely; a few honest tears teach the child it is allowed.', '[{"id": "f0", "type": "textarea", "label": "Draw or describe our handprint heart and the colors we used:"}, {"id": "f1", "type": "textarea", "label": "Something I remember about the person we made it for:"}, {"id": "f2", "type": "textarea", "label": "A memory my parent told me that I did not know:"}, {"id": "f3", "type": "textarea", "label": "The line we wrote inside the heart:"}, {"id": "f4", "type": "textarea", "label": "Where our heart will hang, and why I picked that spot:"}, {"id": "f5", "type": "textarea", "label": "Parent: what my child asked while we made it, and how I answered:"}]'::jsonb, array['grief and loss', 'children', 'craft']::text[], '2026-11-18T15:00:00+00:00'::timestamptz),
  ('group-trip-planning-friction-sheet', 'Group Trip Planning Friction Sheet', 'worksheet'::resource_kind, 'A sheet for the client stuck in a group chat planning a trip, naming the friction, their actual preferences and how to say them.', 'Use it to help a client who goes along with group plans and resents them later speak up before the deposit is paid.', array['Adults', 'Teens']::text[], '20 minutes', 'Group trips expose relationship patterns in miniature: the planner who steamrolls, the friend who agrees to everything and sulks, the one who goes silent until the last minute. The sheet asks the client to name the roles in the chat, their own role, what they actually want from the trip in budget, pace and company, what they have agreed to that they do not want, and one message they could send today that says a preference plainly. Watch for a client who would rather drop out of the trip than send the message.', '[{"id": "f0", "type": "textarea", "label": "The trip, who is in the chat, and the role each person tends to play:"}, {"id": "f1", "type": "textarea", "label": "My role in the chat, honestly:"}, {"id": "f2", "type": "textarea", "label": "What I actually want from this trip: budget, pace, company, one thing I will not do:"}, {"id": "f3", "type": "textarea", "label": "What I have agreed to so far that I do not actually want:"}, {"id": "f4", "type": "textarea", "label": "The message I could send today that states one preference plainly:"}, {"id": "f5", "type": "textarea", "label": "What I am afraid will happen if I send it, and what I think will actually happen:"}]'::jsonb, array['relationship issues', 'assertiveness', 'communication']::text[], '2026-11-18T15:00:00+00:00'::timestamptz),
  ('if-i-bring-it-up-they-will-leave-prediction-sheet', 'If I Bring It Up They Will Leave Prediction Sheet', 'cbt'::resource_kind, 'A prediction sheet for the fear that raising a problem with a partner or friend will end the relationship.', 'Use it to help a client who swallows every grievance test the catastrophe that keeps them silent.', array['Adults', 'Teens']::text[], 'One conversation, then 15 minutes', 'The prediction that raising anything will end the relationship keeps clients silent until the resentment ends it instead. The sheet has them write the issue, the prediction and their confidence, the history of what has actually happened when they or others raised things in this relationship, and the smallest version of the issue to raise first. After the conversation they record what happened in the room and over the next week. Watch for a client who raises it as an ultimatum; the experiment is a plain statement, not a threat.', '[{"id": "f0", "type": "textarea", "label": "The issue I have been swallowing, and how long:"}, {"id": "f1", "type": "textarea", "label": "The prediction, word for word, and my confidence in it from 0 to 100:"}, {"id": "f2", "type": "textarea", "label": "What has actually happened in this relationship when things were raised before, by either of us:"}, {"id": "f3", "type": "textarea", "label": "The smallest version of the issue I could raise first, and the words I will use:"}, {"id": "f4", "type": "textarea", "label": "What happened in the room when I said it:"}, {"id": "f5", "type": "textarea", "label": "What happened over the following week:"}, {"id": "f6", "type": "textarea", "label": "The prediction re-rated, and what I will raise next:"}]'::jsonb, array['relationship issues', 'predictions', 'behavioral experiment']::text[], '2026-11-18T15:00:00+00:00'::timestamptz),
  ('resentment-rent-noticing-page', 'Resentment Rent Noticing Page', 'act'::resource_kind, 'A page that treats a held resentment as rent the client pays daily in attention and mood, and asks what the space could hold instead.', 'Use it to help a client see what carrying a grudge costs them, apart from whether the grudge is justified.', array['Adults', 'Teens']::text[], '20 minutes', 'The page does not ask whether the resentment is fair; many are. It asks what it costs. The client names the resentment, estimates the minutes a day it occupies, what it does to their mood and their behavior toward the person and others, and what the attention could be spent on. Then they decide, not whether to forgive, but whether to keep paying this rent at this rate, and what one small step toward lowering it would be. Watch for a client who hears this as being told to let it go; that is not the ask.', '[{"id": "f0", "type": "textarea", "label": "The resentment I am carrying, in one line, and whether it is justified in my view:"}, {"id": "f1", "type": "textarea", "label": "Roughly how many minutes a day it occupies, and when:"}, {"id": "f2", "type": "textarea", "label": "What it does to my mood and to how I treat the person and other people:"}, {"id": "f3", "type": "textarea", "label": "What that attention and energy could go toward instead:"}, {"id": "f4", "type": "textarea", "label": "Whether I want to keep paying this rent at this rate:"}, {"id": "f5", "type": "textarea", "label": "One small step that would lower the rent without pretending nothing happened:"}]'::jsonb, array['relationship issues', 'metaphor', 'workability']::text[], '2026-11-18T15:00:00+00:00'::timestamptz),
  ('give-skill-at-the-family-dinner-debate-card', 'GIVE Skill at the Family Dinner Debate Card', 'dbt'::resource_kind, 'A GIVE card for staying gentle, interested, validating and easy when a family dinner turns into the usual argument.', 'Use it to help a client keep a relationship intact through a heated dinner they cannot avoid and cannot win.', array['Adults', 'Teens']::text[], 'One dinner, then 10 minutes', 'Some family debates recur every holiday, and the client leaves either silent and seething or having said too much. The card plans the four GIVE moves for the specific relative and the specific topic: a gentle tone even in disagreement, an interested question about why they see it that way, a validation of the feeling under the position, and an easy manner, including a planned exit from the topic. The client notes afterward what they did and how the relationship felt at dessert. Watch for a client who confuses validation with agreement.', '[{"id": "f0", "type": "textarea", "label": "The relative, the topic and how it usually goes:"}, {"id": "f1", "type": "textarea", "label": "Gentle: how I will keep my tone even when I disagree:"}, {"id": "f2", "type": "textarea", "label": "Interested: one question I can ask about why they see it that way:"}, {"id": "f3", "type": "textarea", "label": "Validate: the feeling under their position I can name honestly:"}, {"id": "f4", "type": "textarea", "label": "Easy manner: how I will change the subject or step away without a scene:"}, {"id": "f5", "type": "textarea", "label": "What I did at dinner, and how the relationship felt by dessert:"}]'::jsonb, array['relationship issues', 'GIVE', 'family']::text[], '2026-11-18T15:00:00+00:00'::timestamptz),
  ('compliment-drought-check-sheet-for-partners', 'Compliment Drought Check Sheet for Partners', 'couples'::resource_kind, 'A sheet for partners to notice how long it has been since each gave or received a specific compliment, and restart the flow.', 'Use it to help a couple who still love each other but have stopped saying anything nice notice the drought and end it.', array['Couples']::text[], '20 minutes, then one week', 'Long-term couples often go weeks without a single specific compliment, and each partner assumes the other knows. The sheet has each partner write the last compliment they remember receiving and giving, what they wish their partner noticed, and what gets in the way of saying things. Then they commit to one specific compliment a day for a week, about something the partner did rather than how they look, and log them. Watch for compliments delivered as a chore; the specificity is what makes them land.', '[{"id": "f0", "type": "textarea", "label": "Partner A: the last specific compliment I remember receiving, and when:"}, {"id": "f1", "type": "textarea", "label": "Partner B: the last specific compliment I remember receiving, and when:"}, {"id": "f2", "type": "textarea", "label": "Each of us: something I do that I wish my partner noticed:"}, {"id": "f3", "type": "textarea", "label": "Each of us: what gets in the way of my saying nice things out loud:"}, {"id": "f4", "type": "textarea", "label": "Our week: one specific compliment a day about something the other did:"}, {"id": "f5", "type": "textarea", "label": "Each of us: the compliment this week that landed best, and why:"}, {"id": "f6", "type": "textarea", "label": "What we want to keep doing after the week ends:"}]'::jsonb, array['relationship issues', 'couples', 'appreciation']::text[], '2026-11-18T15:00:00+00:00'::timestamptz),
  ('court-date-steadiness-plan-sheet', 'Court Date Steadiness Plan Sheet', 'worksheet'::resource_kind, 'A steadiness plan for a court date or legal appointment covering who comes, where to wait, grounding tools, breaks and the evening after.', 'Use it to help a client meet a legal step related to abuse with a plan for their body and their support rather than only their testimony.', array['Adults', 'Teens']::text[], '30 minutes, a week before the date', 'A hearing or deposition demands the client''s account; this sheet is for everything else. It asks who will come and what their job is, where the client can wait and breathe away from others, grounding tools for the hallway and the room, how they will ask for a break, what they will eat and drink, and the plan for the evening after, including who they will be with. Keep the sheet away from the content of what happened; that belongs with their attorney and advocate. Watch for a client with no one to bring; a victim advocate may be available through the court.', '[{"id": "f0", "type": "textarea", "label": "Who is coming with me, and the job I am asking each of them to do:"}, {"id": "f1", "type": "textarea", "label": "Where I can wait and breathe away from other people, and how I will find it:"}, {"id": "f2", "type": "textarea", "label": "Grounding tools for the hallway and for the room, within reach:"}, {"id": "f3", "type": "textarea", "label": "How I will ask for a break, in exact words, and who I will say them to:"}, {"id": "f4", "type": "textarea", "label": "What I will eat and drink that day, and when:"}, {"id": "f5", "type": "textarea", "label": "The plan for the evening after: where I will be, and who with:"}, {"id": "f6", "type": "textarea", "label": "What I will tell myself on the drive there:"}]'::jsonb, array['sexual abuse', 'stabilizing', 'safety']::text[], '2026-11-18T15:00:00+00:00'::timestamptz),
  ('i-attract-bad-people-belief-gentle-check-sheet', 'I Attract Bad People Belief Gentle Check Sheet', 'cbt'::resource_kind, 'A gentle check of the belief that the client somehow draws harmful people to them, examining where blame sits and what it costs.', 'Use it to help a survivor who has concluded they are the common cause of what was done to them look at that conclusion with care.', array['Adults', 'Teens']::text[], '25 minutes, in session', 'Survivors often arrive at a belief that explains everything at their own expense: there is something about me that attracts this. The sheet names the belief, asks where responsibility for a harmful act sits by the client''s own rule when applied to someone else, lists the people in their life who have been safe, notes what the belief makes them do and avoid now, and offers a fairer sentence. Complete it in session, slowly, without asking for details of any event. Watch for the belief protecting the client from a scarier idea, that it was random.', '[{"id": "f0", "type": "textarea", "label": "The belief, in my own words, and how much I believe it from 0 to 100:"}, {"id": "f1", "type": "textarea", "label": "By my own rule, who is responsible when one person harms another:"}, {"id": "f2", "type": "textarea", "label": "People in my life who have been safe with me, however few:"}, {"id": "f3", "type": "textarea", "label": "What the belief makes me do, and what it makes me avoid, now:"}, {"id": "f4", "type": "textarea", "label": "What the belief might be protecting me from believing instead:"}, {"id": "f5", "type": "textarea", "label": "A fairer sentence about me and about what was done, written with my clinician:"}]'::jsonb, array['sexual abuse', 'self-blame', 'core beliefs']::text[], '2026-11-18T15:00:00+00:00'::timestamptz),
  ('my-body-is-mine-today-values-page', 'My Body Is Mine Today Values Page', 'act'::resource_kind, 'A values page for small daily choices about the client''s own body, clothing, touch and rest, made on purpose as acts of ownership.', 'Use it to help a survivor practice authorship over their own body in ordinary, present-day moments.', array['Adults', 'Teens']::text[], '15 minutes, then daily', 'The page stays in the present and keeps the stakes small. The client writes what ownership of their body would look like today in choices nobody else sees: what to wear, whether to be touched and by whom, when to rest, how to move. They pick one choice a day to make deliberately and note it, along with what the mind said. It is not an exposure plan and does not involve anyone else''s touch unless the client chooses that. Watch for a client who treats the page as a to-do list of things they should be able to do.', '[{"id": "f0", "type": "textarea", "label": "What ownership of my body would look like today, in choices only I would notice:"}, {"id": "f1", "type": "textarea", "label": "The one choice I will make on purpose today:"}, {"id": "f2", "type": "textarea", "label": "What my mind said while I made it:"}, {"id": "f3", "type": "textarea", "label": "Each day this week: the choice, and how it felt afterward:"}, {"id": "f4", "type": "textarea", "label": "A choice I am not ready to make yet, and that is allowed:"}, {"id": "f5", "type": "textarea", "label": "What I want my body to know about who is in charge now:"}]'::jsonb, array['sexual abuse', 'values', 'stabilizing']::text[], '2026-11-18T15:00:00+00:00'::timestamptz),
  ('self-soothe-with-scent-after-a-hard-session-card', 'Self-Soothe With Scent After a Hard Session Card', 'dbt'::resource_kind, 'A self-soothe card using one chosen scent to mark the end of a hard session and the return to the rest of the day.', 'Use it to give a survivor a portable sensory anchor for the walk from the office to the car and the hours after.', array['Adults', 'Teens']::text[], 'Two minutes after each session', 'Scent reaches the body quickly and can be carried in a pocket. The client chooses one scent that means safe and present, a hand lotion, a tea bag, a sprig of rosemary, and uses it only after sessions at first so the pairing is strong. The card has them breathe it in for a few slow breaths before leaving the building, note where they are in the body afterward, and plan the first hour. Avoid any scent connected to the past. Watch for a client who skips it when the session was hardest, which is when it is for.', '[{"id": "f0", "type": "textarea", "label": "The scent I chose, and why it means safe and present to me:"}, {"id": "f1", "type": "textarea", "label": "Where I will keep it so it is in my hand before I leave the building:"}, {"id": "f2", "type": "textarea", "label": "After today''s session: a few slow breaths with it, and where I am in my body now:"}, {"id": "f3", "type": "textarea", "label": "My plan for the first hour after I leave:"}, {"id": "f4", "type": "textarea", "label": "Over several weeks: what the scent has started to do on its own:"}]'::jsonb, array['sexual abuse', 'self-soothing', 'grounding']::text[], '2026-11-18T15:00:00+00:00'::timestamptz),
  ('personal-space-bubble-hula-hoop-play', 'Personal Space Bubble Hula Hoop Play', 'kids'::resource_kind, 'A play activity using a hula hoop as a child''s personal space bubble, practicing asking before entering and saying no to entering.', 'Use it to teach a child in a playful, concrete way that their space is theirs and that asking first is the rule for everyone.', array['Children']::text[], '20 minutes', 'The child stands inside a hula hoop that is their bubble. The parent and child take turns approaching and asking may I come into your bubble, and the one inside practices yes, no and not right now with their whole voice. Then they swap, and the child practices asking and hearing a no without arguing. Add silly characters, a puppet who forgets to ask and gets a firm no. Keep it light and let the child set every rule about their hoop. If a child discloses anything during play, respond calmly and remember your reporting duties.', '[{"id": "f0", "type": "textarea", "label": "Draw my bubble and who is allowed to ask to come in:"}, {"id": "f1", "type": "textarea", "label": "The words I use for yes, for no and for not right now:"}, {"id": "f2", "type": "textarea", "label": "What I did when the puppet forgot to ask:"}, {"id": "f3", "type": "textarea", "label": "How it felt to hear a no when I asked to come into someone''s bubble:"}, {"id": "f4", "type": "textarea", "label": "A grown-up I can tell if someone comes into my bubble without asking:"}, {"id": "f5", "type": "textarea", "label": "Parent: the rules my child set for their hoop, and how I followed them:"}]'::jsonb, array['sexual abuse', 'children', 'body safety']::text[], '2026-11-18T15:00:00+00:00'::timestamptz),
  ('coping-skills-i-only-use-in-session-transfer-sheet', 'Coping Skills I Only Use in Session Transfer Sheet', 'worksheet'::resource_kind, 'A sheet listing the skills a client can do in the room but never at home, with what is missing out there and a plan to carry one across.', 'Use it to close the gap between what a client knows how to do with you and what they actually do on a hard Tuesday.', array['Adults', 'Teens']::text[], '20 minutes, then one week', 'Many clients have a dozen skills they can demonstrate on request and none they reach for in the moment. The sheet has them list the skills they can do in session, rate how often each has happened outside, and for each name what is missing at home: a cue, a prop, privacy, a reminder, permission. Then they pick one skill and build its home version, including where the prop lives and what cue triggers it. Watch for a client who wants to transfer all twelve; one that actually travels beats twelve that stay in the room.', '[{"id": "f0", "type": "textarea", "label": "Skills I can do in session when asked:"}, {"id": "f1", "type": "textarea", "label": "For each: how many times I have actually used it outside this room:"}, {"id": "f2", "type": "textarea", "label": "For each: what is missing out there, such as a cue, a prop, privacy or a reminder:"}, {"id": "f3", "type": "textarea", "label": "The one skill I will move home this week:"}, {"id": "f4", "type": "textarea", "label": "Its home version: where the prop lives, what the cue is, what the first step looks like:"}, {"id": "f5", "type": "textarea", "label": "After a week: did it travel, and what got in the way when it did not?"}]'::jsonb, array['coping skills', 'skills', 'planning']::text[], '2026-11-18T15:00:00+00:00'::timestamptz),
  ('if-i-need-a-skill-the-day-is-already-ruined-check-sheet', 'If I Need a Skill the Day Is Already Ruined Check Sheet', 'cbt'::resource_kind, 'A thought check for the belief that having to use a coping skill means the day has already failed.', 'Use it to help a client who treats reaching for a skill as defeat see it as the moment the day was saved.', array['Adults', 'Teens']::text[], '15 minutes', 'Some clients avoid their skills because using one feels like admitting the day went wrong. The sheet names the thought, rates belief in it, lists days this month when a skill was used and how the rest of the day went, compares them with days a skill was needed and not used, and asks what they think of other people who use skills, from athletes to pilots. Then they rewrite the sentence. Watch for the perfectionism underneath, the wish for a day that never needs anything.', '[{"id": "f0", "type": "textarea", "label": "The thought, in my words, and how much I believe it from 0 to 100:"}, {"id": "f1", "type": "textarea", "label": "Days this month when I used a skill, and how the rest of the day went:"}, {"id": "f2", "type": "textarea", "label": "Days a skill was needed and I did not use one, and how those went:"}, {"id": "f3", "type": "textarea", "label": "What I think of other people who use skills on purpose, from athletes to pilots:"}, {"id": "f4", "type": "textarea", "label": "What I wish were true about my days that this thought is protecting:"}, {"id": "f5", "type": "textarea", "label": "The sentence rewritten, and the belief re-rated:"}]'::jsonb, array['coping skills', 'thinking traps', 'perfectionism']::text[], '2026-11-18T15:00:00+00:00'::timestamptz),
  ('willingness-dial-before-the-skill-page', 'Willingness Dial Before the Skill Page', 'act'::resource_kind, 'A page that checks the client''s willingness to have the feeling before choosing a coping skill, so the skill is not used to escape it.', 'Use it to help a client tell the difference between coping to live their day and coping to escape every feeling.', array['Adults', 'Teens']::text[], 'Five minutes before a skill, for one week', 'A coping skill used to banish a feeling often becomes avoidance in a healthier outfit. The page asks, before the skill, where the willingness dial sits from 0 to 10, what the feeling is, what the client wants the skill to do, and what they will do next if the feeling stays. Then they use the skill and note what happened to the feeling and to the day. Over a week they look at the relationship between the dial and how the skill worked. Watch for a client who scores the skill a failure when the feeling remained but the day went on.', '[{"id": "f0", "type": "textarea", "label": "Before the skill: the feeling, and where my willingness dial sits from 0 to 10:"}, {"id": "f1", "type": "textarea", "label": "What I want the skill to do, honestly: get rid of it, or help me carry it:"}, {"id": "f2", "type": "textarea", "label": "What I will do next if the feeling is still there afterward:"}, {"id": "f3", "type": "textarea", "label": "After the skill: what happened to the feeling, and what happened to the day:"}, {"id": "f4", "type": "textarea", "label": "Over the week: what I notice about the dial and how the skills worked:"}, {"id": "f5", "type": "textarea", "label": "A skill I use mostly to escape, and one I use mostly to live:"}]'::jsonb, array['coping skills', 'willingness', 'workability']::text[], '2026-11-18T15:00:00+00:00'::timestamptz),
  ('improve-the-moment-imagery-card', 'IMPROVE the Moment Imagery Card', 'dbt'::resource_kind, 'An IMPROVE card focused on the I, imagery, building one detailed safe or pleasant scene the client can enter for two minutes.', 'Use it to give a client a ready-made scene for the moments when the environment cannot change and the mind can.', array['Adults', 'Teens', 'Groups']::text[], '15 minutes to build, two minutes to use', 'The imagery skill works only if the scene is built in advance and in detail. The card has the client choose a real or invented place, fill in all five senses, add what they are doing there and who, if anyone, is present, and give it a short name. They practice entering it for two minutes in session, then use it in a waiting room or a hard evening and note how long it took to arrive and what it did. Watch for a scene with a hidden stressor in it, such as a beach with a crowd; edit until it is clean.', '[{"id": "f0", "type": "textarea", "label": "My scene: the place, real or invented, and its short name:"}, {"id": "f1", "type": "textarea", "label": "What I see, hear, feel on my skin, smell and taste there:"}, {"id": "f2", "type": "textarea", "label": "What I am doing in the scene, and who if anyone is with me:"}, {"id": "f3", "type": "textarea", "label": "In session: how long it took to arrive, and what shifted in my body:"}, {"id": "f4", "type": "textarea", "label": "This week: when I used it, how long it took, and what it did:"}, {"id": "f5", "type": "textarea", "label": "One detail I will add or remove to make the scene stronger:"}]'::jsonb, array['coping skills', 'distress tolerance', 'IMPROVE']::text[], '2026-11-18T15:00:00+00:00'::timestamptz),
  ('coping-skill-elevator-pitch-thirty-seconds-game', 'Coping Skill Elevator Pitch Thirty Seconds Game', 'game'::resource_kind, 'A group game in which each member has thirty seconds to sell a coping skill to the room, and the room votes on which pitch they would try.', 'Use it to get a group teaching each other skills with energy, and to find out which skills people actually find convincing.', array['Groups', 'Teens', 'Adults']::text[], '25 minutes', 'Each member draws or chooses a coping skill and has thirty seconds, timed, to pitch it: what it is, when it works, why the room should try it this week. No notes. After all pitches, everyone votes for the one skill, not their own, they will actually try, and the winners say what sold them. Debrief on what made a pitch convincing and which skills nobody voted for and why. Watch for a member who pitches a skill they have never used; ask them to try it before next week and report back.', '[{"id": "f0", "type": "textarea", "label": "The skill I pitched, and my thirty seconds in a few lines:"}, {"id": "f1", "type": "textarea", "label": "The pitch I voted for, and what sold me:"}, {"id": "f2", "type": "textarea", "label": "A skill nobody voted for, and why I think it did not land:"}, {"id": "f3", "type": "textarea", "label": "What made the convincing pitches convincing:"}, {"id": "f4", "type": "textarea", "label": "The skill I will try this week because of a pitch, and when:"}]'::jsonb, array['coping skills', 'game', 'group']::text[], '2026-11-18T15:00:00+00:00'::timestamptz),
  ('snake-picture-to-video-to-zoo-step-plan-sheet', 'Snake Picture to Video to Zoo Step Plan Sheet', 'worksheet'::resource_kind, 'A step plan for a fear of snakes that moves from a cartoon drawing through photos and videos to the glass at the reptile house.', 'Use it to help a client who cannot look at a snake build a ladder of steps they choose and can repeat.', array['Adults', 'Teens']::text[], 'Four to eight weeks', 'The sheet lays out a ladder with the client: a cartoon snake, a photo, a photo on the phone held closer, a short video with the sound off, a longer one with sound, a documentary clip, and finally standing at the glass at a zoo for a set number of minutes. For each step they predict fear from 0 to 100, stay until it drops noticeably, repeat, and record the actual peak and how long it took to ease. Let the client set the order and add rungs. Watch for a client who scrolls past the picture quickly and counts it done.', '[{"id": "f0", "type": "textarea", "label": "My ladder, from the easiest step to the glass at the reptile house, in my order:"}, {"id": "f1", "type": "textarea", "label": "This week''s step, and my predicted peak fear from 0 to 100:"}, {"id": "f2", "type": "textarea", "label": "How long I stayed with it, and the actual peak and where it ended:"}, {"id": "f3", "type": "textarea", "label": "How many times I repeated the step, and how the peak changed:"}, {"id": "f4", "type": "textarea", "label": "What the fear said I should do, and what I did instead:"}, {"id": "f5", "type": "textarea", "label": "The next rung, and what would make this one a little harder first:"}]'::jsonb, array['phobias', 'exposure', 'hierarchy']::text[], '2026-11-18T15:00:00+00:00'::timestamptz),
  ('fainting-at-the-needle-will-be-mocked-prediction-sheet', 'Fainting at the Needle Will Be Mocked Prediction Sheet', 'cbt'::resource_kind, 'A prediction sheet for the social fear wrapped around a needle fear: that fainting or flinching will be mocked by staff or onlookers.', 'Use it to help a client separate the fear of the needle from the fear of what people will think if they react.', array['Adults', 'Teens']::text[], '20 minutes before an appointment, 10 after', 'For many clients the needle is only half of it; the rest is the imagined audience. The sheet has them write both fears separately, rate each, predict exactly what staff and anyone else present would do if they flinched, went pale or fainted, and list what they have actually seen staff do with nervous patients. After the appointment they record what the staff actually said and did, and whether anyone laughed. Pair with tensing practice for the fainting itself if that is part of the picture. Watch for the client who avoids appointments entirely.', '[{"id": "f0", "type": "textarea", "label": "The fear of the needle itself, rated 0 to 100, and the fear of how I will look, rated separately:"}, {"id": "f1", "type": "textarea", "label": "What I predict the staff would do if I flinched, went pale or fainted:"}, {"id": "f2", "type": "textarea", "label": "What I predict anyone else in the room would do:"}, {"id": "f3", "type": "textarea", "label": "What I have actually seen medical staff do with nervous patients:"}, {"id": "f4", "type": "textarea", "label": "After the appointment: what the staff actually said and did:"}, {"id": "f5", "type": "textarea", "label": "Did anyone laugh? What does that do to the prediction for next time?"}]'::jsonb, array['phobias', 'predictions', 'social anxiety']::text[], '2026-11-18T15:00:00+00:00'::timestamptz),
  ('carrying-the-fear-across-the-bridge-willingness-page', 'Carrying the Fear Across the Bridge Willingness Page', 'act'::resource_kind, 'A willingness page for crossing a bridge the client avoids, taking the fear along as a passenger rather than waiting for it to leave.', 'Use it to help a client whose detours around bridges cost hours practice crossing with the fear present.', array['Adults', 'Teens']::text[], 'One crossing, then 10 minutes', 'Bridge fears often lead to long detours and declined invitations, and the client waits for a day without fear that never comes. The page has them name the bridge, what crossing it serves, the fear they expect and where it sits in the body, and a willingness rating for taking it along. They cross, as passenger first if they prefer, and record what the fear did at the start, the middle and the far side. Watch for a client who crosses white-knuckled and calls it done; ask what they noticed about the view.', '[{"id": "f0", "type": "textarea", "label": "The bridge, and what I have done to avoid it, in time and miles:"}, {"id": "f1", "type": "textarea", "label": "What crossing it serves: a person, a place, my own freedom to go where I like:"}, {"id": "f2", "type": "textarea", "label": "The fear I expect, and where in my body it will ride:"}, {"id": "f3", "type": "textarea", "label": "My willingness to take it along, from 0 to 10:"}, {"id": "f4", "type": "textarea", "label": "What the fear did at the start, the middle and the far side:"}, {"id": "f5", "type": "textarea", "label": "What I noticed about the view, the sound or the road that I had never noticed:"}, {"id": "f6", "type": "textarea", "label": "The next crossing, and whether I will drive it myself:"}]'::jsonb, array['phobias', 'willingness', 'avoidance']::text[], '2026-11-18T15:00:00+00:00'::timestamptz),
  ('half-smile-at-the-spider-card', 'Half Smile at the Spider Card', 'dbt'::resource_kind, 'A half-smile and willing-hands card for being in a room with a spider or insect, changing the body''s stance before the mind catches up.', 'Use it to give a client a small physical move for the moment of spotting a spider, instead of the leap for the door.', array['Adults', 'Teens']::text[], 'Two minutes when a spider appears', 'A half smile and open hands send the body a different message than a grimace and clenched fists, and the mind tends to follow the body. The card has the client practice the half smile, lips barely turned up, face relaxed, and willing hands, palms open and turned up, first in session with a photo, then at home with a real spider at a distance they choose. They rate fear before and after two minutes and note whether they stayed in the room. Watch for a forced grin, which is not the skill. Pair it with their exposure ladder.', '[{"id": "f0", "type": "textarea", "label": "Where the spider was, and how far away I chose to be:"}, {"id": "f1", "type": "textarea", "label": "My fear before the half smile and willing hands, from 0 to 100:"}, {"id": "f2", "type": "textarea", "label": "What my face and hands were doing before I noticed them:"}, {"id": "f3", "type": "textarea", "label": "Two minutes of half smile and open hands: what my body did, and what my mind did:"}, {"id": "f4", "type": "textarea", "label": "My fear after, and whether I stayed in the room:"}, {"id": "f5", "type": "textarea", "label": "The distance I will try next time:"}]'::jsonb, array['phobias', 'distress tolerance', 'half smile']::text[], '2026-11-18T15:00:00+00:00'::timestamptz),
  ('feared-thing-trivia-quiz-game', 'Feared Thing Trivia Quiz Game', 'game'::resource_kind, 'A trivia game in which teams answer plain-fact questions about commonly feared things, from spiders to elevators to turbulence.', 'Use it to lower the temperature around a feared object in a group with facts, laughter and a scoreboard.', array['Groups', 'Teens', 'Adults']::text[], '30 minutes', 'The facilitator prepares twenty short factual questions about feared things, how many legs a spider has, how an elevator brake works, what turbulence is, how long a thunderstorm usually lasts, with the answers checked in advance from reliable sources. Teams confer and answer; points for correct answers, bonus points for a team that says what they used to believe instead. Debrief on which facts surprised the room and which did nothing for the fear, which is useful to notice. Watch for a member for whom even the questions are too much; let them keep score.', '[{"id": "f0", "type": "textarea", "label": "The fact that surprised me most tonight:"}, {"id": "f1", "type": "textarea", "label": "A question about my own feared thing, and what I used to believe instead of the answer:"}, {"id": "f2", "type": "textarea", "label": "A fact that did nothing at all for my fear, and what that tells me:"}, {"id": "f3", "type": "textarea", "label": "A question I would add to the quiz next time:"}, {"id": "f4", "type": "textarea", "label": "One fact I will remember the next time I meet the thing I fear:"}]'::jsonb, array['phobias', 'game', 'psychoeducation']::text[], '2026-11-18T15:00:00+00:00'::timestamptz),
  ('tagged-photo-untag-urge-log', 'Tagged Photo Untag Urge Log', 'worksheet'::resource_kind, 'A log of every urge to untag, hide or ask someone to delete a photo of the client, with the thought behind it and what they did.', 'Use it to make the photo-policing habit visible and give the client a choice about which photos get to exist.', array['Adults', 'Teens']::text[], 'Two weeks', 'Untagging and deleting photos is a quiet daily ritual for many clients with body image distress, and it erases them from their own history. The log records each urge: the photo, the thought about how they looked, who else was in it, what they did, and how they felt an hour later. At the end of two weeks they count the urges and the deletions and look at what the photos were actually of: a birthday, a trip, a friend''s wedding. Watch for the client who asks others to take photos down; that belongs on the log too.', '[{"id": "f0", "type": "textarea", "label": "Each urge: the photo, who took it, and who else was in it:"}, {"id": "f1", "type": "textarea", "label": "The thought about how I looked, word for word:"}, {"id": "f2", "type": "textarea", "label": "What I did: untagged, hid, asked for a deletion, left it:"}, {"id": "f3", "type": "textarea", "label": "How I felt an hour later:"}, {"id": "f4", "type": "textarea", "label": "After two weeks: the count of urges and deletions, and what the photos were actually of:"}, {"id": "f5", "type": "textarea", "label": "One photo I will leave up this week, and what I will tell myself when the urge comes:"}]'::jsonb, array['body image', 'self-monitoring', 'avoidance']::text[], '2026-11-18T15:00:00+00:00'::timestamptz),
  ('everyone-noticed-the-blemish-thought-record', 'Everyone Noticed the Blemish Thought Record', 'cbt'::resource_kind, 'A thought record for a visible blemish, breakout or mark that the client is certain every person they met was staring at.', 'Use it to help a client test the spotlight they feel on one feature against what people actually noticed and said.', array['Adults', 'Teens']::text[], '15 minutes', 'A single blemish can take over a client''s whole day, and they read every glance as confirmation. The record captures the feature, the thought, the feeling and its strength, how many people they interacted with, how many mentioned it, how many they saw look at it versus assumed did, and what they themselves notice about other people''s skin on a normal day. It ends with a fairer thought and a plan for the next appearance of the spotlight. Watch for concealing behaviors that keep the belief untested.', '[{"id": "f0", "type": "textarea", "label": "The feature I am sure everyone noticed, and how long I spent on it this morning:"}, {"id": "f1", "type": "textarea", "label": "The thought, word for word, and the feeling with its strength from 0 to 100:"}, {"id": "f2", "type": "textarea", "label": "How many people I interacted with today, and how many said anything about it:"}, {"id": "f3", "type": "textarea", "label": "How many I actually saw look at it, versus how many I assumed did:"}, {"id": "f4", "type": "textarea", "label": "What I notice about other people''s skin on an ordinary day, honestly:"}, {"id": "f5", "type": "textarea", "label": "A fairer thought, and what I will do differently the next time the spotlight comes on:"}]'::jsonb, array['body image', 'thought record', 'thinking traps']::text[], '2026-11-18T15:00:00+00:00'::timestamptz),
  ('body-as-a-home-i-live-in-not-a-house-i-sell-page', 'Body as a Home I Live In Not a House I Sell Page', 'act'::resource_kind, 'A values page that reframes the body from a property kept presentable for viewers to a home the client actually lives in.', 'Use it to help a client shift from curating how the body looks to others toward what it is for in their own life.', array['Adults', 'Teens']::text[], '20 minutes', 'Clients with body image distress often treat the body like a house on the market, staged for buyers and never lived in. The page asks what the body as a house for sale requires of them each day, what a home they lived in would be used for, which rooms, meaning activities and places, they have closed off to viewers, and one room they will reopen this week. The language stays off looks and measures entirely. Watch for a client who turns reopening a room into a performance for someone else''s approval.', '[{"id": "f0", "type": "textarea", "label": "What keeping my body staged for viewers requires of me each day:"}, {"id": "f1", "type": "textarea", "label": "What I would use this body for if it were a home I lived in, not a house I was selling:"}, {"id": "f2", "type": "textarea", "label": "The rooms I have closed off, meaning the activities and places I avoid because of how I might look:"}, {"id": "f3", "type": "textarea", "label": "The room I will reopen this week, and what I will do in it:"}, {"id": "f4", "type": "textarea", "label": "What the mind says about viewers when I start to live in it:"}, {"id": "f5", "type": "textarea", "label": "The value that living in it serves, in one word:"}]'::jsonb, array['body image', 'values', 'metaphor']::text[], '2026-11-18T15:00:00+00:00'::timestamptz),
  ('describe-not-judge-scrolling-the-fashion-feed-card', 'Describe Not Judge Scrolling the Fashion Feed Card', 'dbt'::resource_kind, 'A Describe card for scrolling fashion or fitness content, naming only what is literally in each image before the comparison starts.', 'Use it to help a client who cannot stop scrolling see what the feed is actually made of and what their mind adds to it.', array['Adults', 'Teens']::text[], 'Ten minutes of scrolling, three times a week', 'If a client is going to scroll anyway, the Describe skill can change what the scrolling does. The card has them scroll for ten minutes and, for each image that hooks them, write only what is literally there: lighting, pose, filter, angle, product, caption. Then separately, what the mind added: the comparison, the verdict on themselves. Over a week they look at how often the first list contains the words professional, posed or edited. Watch for the client whose describing becomes a new way of inspecting bodies; keep the words to the frame, not the figure.', '[{"id": "f0", "type": "textarea", "label": "Image one: only what is literally there, such as lighting, pose, filter, angle, product, caption:"}, {"id": "f1", "type": "textarea", "label": "Image one: what my mind added:"}, {"id": "f2", "type": "textarea", "label": "Image two: only what is literally there:"}, {"id": "f3", "type": "textarea", "label": "Image two: what my mind added:"}, {"id": "f4", "type": "textarea", "label": "How many of my first lists included the words posed, professional, filtered or edited:"}, {"id": "f5", "type": "textarea", "label": "What ten minutes of describing did to the feed compared to ten minutes of judging:"}]'::jsonb, array['body image', 'mindfulness', 'describe']::text[], '2026-11-18T15:00:00+00:00'::timestamptz),
  ('clothes-shopping-trip-support-plan-for-partners', 'Clothes Shopping Trip Support Plan for Partners', 'couples'::resource_kind, 'A plan for partners before a clothes shopping trip covering what helps, what to never say, when to wait outside and how it ends.', 'Use it to help a couple get through a shopping trip without the fitting room becoming a fight about bodies.', array['Couples']::text[], '20 minutes before the trip', 'A shopping trip with a partner can go wrong in one sentence. The sheet has the partner with body image distress write what actually helps, the comments that make it worse even when kind, whether they want company at the fitting room or a coffee nearby, and the signal for we are done; the other partner writes what they can offer, what they find hard about the trip, and the questions they will ask instead of comments on how things look. Keep the agreement off appearance entirely. Watch for the trip ending in reassurance-seeking loops.', '[{"id": "f0", "type": "textarea", "label": "Partner with body image distress: what actually helps me on a shopping trip:"}, {"id": "f1", "type": "textarea", "label": "Partner with body image distress: the comments that make it worse, even kind ones:"}, {"id": "f2", "type": "textarea", "label": "Partner with body image distress: whether I want you at the fitting room or nearby, and my signal for done:"}, {"id": "f3", "type": "textarea", "label": "Other partner: what I can offer, and what I find hard about these trips:"}, {"id": "f4", "type": "textarea", "label": "Other partner: the questions I will ask instead of commenting on how things look, such as is it comfortable:"}, {"id": "f5", "type": "textarea", "label": "Our plan for how the trip ends, whatever we did or did not buy:"}, {"id": "f6", "type": "textarea", "label": "After the trip: what worked, for the next one:"}]'::jsonb, array['body image', 'couples', 'support']::text[], '2026-11-18T15:00:00+00:00'::timestamptz)
